     2→import { db, ref, onValue, set, update, remove, get } from '../lib/firebase';
     3→import { getTeamDashboard } from '../lib/roadToNationals';
     4→import { normalizeName, getLookupKeys } from '../lib/nameNormalization';
     5→
     6→/**
     7→ * Fetch all headshots from Firebase teamsDatabase
     8→ * Returns a map with multiple keys per headshot for flexible matching
     9→ * Keys include: normalized name, stripped version, Firebase key variant
    10→ */
    11→async function getFirebaseHeadshots() {
    12→  try {
    13→    const headshotsRef = ref(db, 'teamsDatabase/headshots');
    14→    const snapshot = await get(headshotsRef);
    15→    const headshotsData = snapshot.val() || {};
    16→
    17→    // Build a map with multiple keys per headshot for flexible matching
    18→    const headshotMap = {};
    19→    for (const [key, data] of Object.entries(headshotsData)) {
    20→      if (data?.url) {
    21→        // Store by Firebase key (underscores → spaces)
    22→        const keyWithSpaces = key.toLowerCase().trim().replace(/_/g, ' ').replace(/\s+/g, ' ');
    23→        headshotMap[keyWithSpaces] = data.url;
    24→
    25→        // Store by fully normalized key
    26→        const normalizedKey = normalizeName(key);
    27→        headshotMap[normalizedKey] = data.url;
    28→
    29→        // Store by name field if available
    30→        if (data.name) {
    31→          headshotMap[normalizeName(data.name)] = data.url;
    32→          // Also store just lowercased version
    33→          headshotMap[data.name.toLowerCase().trim().replace(/\s+/g, ' ')] = data.url;
    34→        }
    35→
    36→        // Store stripped version (only letters and spaces)
    37→        const strippedKey = normalizedKey.replace(/[^a-z\s]/g, '').replace(/\s+/g, ' ').trim();
    38→        if (strippedKey && strippedKey.length > 2) {
    39→          headshotMap[strippedKey] = data.url;
    40→        }
    41→      }
    42→    }
    43→    return headshotMap;
    44→  } catch (err) {
    45→    console.error('Failed to fetch Firebase headshots:', err);
    46→    return {};
    47→  }
    48→}
    49→
    50→/**
    51→ * Look up a headshot URL from the headshot map using multiple lookup keys
    52→ * Handles accents, hyphens, apostrophes, and other edge cases
    53→ */
    54→function lookupHeadshot(headshotMap, firstName, lastName) {
    55→  if (!firstName && !lastName) return null;
    56→
    57→  // Get all possible lookup keys for this name
    58→  const keys = getLookupKeys(firstName, lastName);
    59→
    60→  // Try each key until we find a match
    61→  for (const key of keys) {
    62→    if (headshotMap[key]) {
    63→      return headshotMap[key];
    64→    }
    65→  }
    66→
    67→  return null;
    68→}
    69→
    70→/**
    71→ * Parse Virtius roster HTML to extract RTN IDs and headshot URLs
    72→ * @param {string} html - Raw HTML from Virtius roster table
    73→ * @returns {Array<{rtnId: string, headshotUrl: string, name: string}>}
    74→ */
    75→export function parseVirtiusRosterHtml(html) {
    76→  const results = [];
    77→
    78→  // Match each row: find athlete name, headshot URL, and RTN ID
    79→  // Pattern: img src for headshot, then name in a div, then rtnId in an input
    80→  const rowRegex = /<tr[^>]*role="row"[^>]*>([\s\S]*?)<\/tr>/gi;
    81→  const imgRegex = /src="(https:\/\/media\.virti\.us\/upload\/images\/athlete\/[^"]+)"/i;
    82→  const nameRegex = /alt="([^"]+)\s+Profile"/i;
