   591→function RosterView({ teamKey, teams, getTeamRosterWithHeadshots }) {
   592→  const roster = getTeamRosterWithHeadshots(teamKey);
   593→  const team = teams[teamKey];
   594→
   595→  if (!roster || roster.length === 0) {
   596→    return (
   597→      <div className="p-4 border-t border-zinc-700 text-center">
   598→        <p className="text-zinc-500 text-sm">No roster defined for {team?.displayName || teamKey}</p>
   599→        <p className="text-xs text-zinc-600 mt-1">Use "Import from Virtius" below to add athletes</p>
   600→      </div>
   601→    );
   602→  }
   603→
   604→  return (
   605→    <div className="p-4 border-t border-zinc-700">
   606→      <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 gap-2 max-h-64 overflow-y-auto">
   607→        {roster.map((athlete, idx) => (
   608→          <div
   609→            key={idx}
   610→            className="flex items-center gap-2 p-2 bg-zinc-700/50 rounded"
   611→          >
   612→            <div className="w-8 h-8 bg-zinc-600 rounded-full flex items-center justify-center overflow-hidden flex-shrink-0">
   613→              {athlete.hasHeadshot ? (
   614→                <img src={athlete.headshotUrl} alt={athlete.name} className="w-8 h-8 object-cover" />
   615→              ) : (
   616→                <UserGroupIcon className="w-4 h-4 text-zinc-500" />
   617→              )}
   618→            </div>
   619→            <span className="text-xs text-zinc-300 truncate flex-1">{athlete.name}</span>
   620→            {athlete.hasHeadshot ? (
   621→              <CheckCircleIcon className="w-3 h-3 text-green-500 flex-shrink-0" />
   622→            ) : (
   623→              <XCircleIcon className="w-3 h-3 text-red-500 flex-shrink-0" />
   624→            )}
   625→          </div>
   626→        ))}
   627→      </div>
   628→    </div>
   629→  );
   630→}
   631→
   632→function TeamInfoDisplay({ teamName, gender }) {
   633→  const { dashboard, loading } = useTeamDashboard(teamName, gender);
   634→
   635→  if (loading) {
   636→    return (
   637→      <div className="flex items-center justify-center py-8">
   638→        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-cyan-500"></div>
   639→        <span className="ml-3 text-zinc-400">Loading team data from Road to Nationals...</span>
   640→      </div>
   641→    );
   642→  }
   643→
   644→  // Derive all data from the single dashboard response
   645→  const staff = dashboard?.staff
   646→    ?.filter(s => s.position?.toLowerCase().includes('coach'))
   647→    .map(s => ({
   648→      id: s.id,
   649→      fullName: `${s.first_name?.trim() || ''} ${s.last_name?.trim() || ''}`.trim(),
   650→      position: s.position,
   651→      imageUrl: s.image_url ? `https://www.roadtonationals.com/images/staff/${s.image_url}` : null,
   652→    }))
   653→    .sort((a, b) => {
   654→      if (a.position?.toLowerCase().includes('head')) return -1;
   655→      if (b.position?.toLowerCase().includes('head')) return 1;
   656→      return 0;
   657→    }) || [];
   658→
   659→  const links = {};
   660→  if (dashboard?.links) {
   661→    for (const link of dashboard.links) {
   662→      const type = link.tax_value?.toLowerCase() || '';
   663→      if (type.includes('facebook')) links.facebook = link.link;
   664→      else if (type.includes('twitter')) links.twitter = link.link;
   665→      else if (type.includes('instagram')) links.instagram = link.link;
   666→      else if (type.includes('official')) links.officialSite = link.link;
   667→    }
   668→  }
   669→
   670→  const ranks = dashboard?.ranks;
   671→  const rankings = ranks ? (gender === 'womens' ? {
   672→    vault: ranks.vault ? parseInt(ranks.vault) : null,
   673→    bars: ranks.bars ? parseInt(ranks.bars) : null,
   674→    beam: ranks.beam ? parseInt(ranks.beam) : null,
   675→    floor: ranks.floor ? parseInt(ranks.floor) : null,
   676→    team: ranks.team ? parseInt(ranks.team) : null,
   677→  } : {
   678→    floor: ranks.floor ? parseInt(ranks.floor) : null,
   679→    pommel: ranks.pommel ? parseInt(ranks.pommel) : null,
   680→    rings: ranks.rings ? parseInt(ranks.rings) : null,
   681→    vault: ranks.vault ? parseInt(ranks.vault) : null,
   682→    pBars: ranks.pbars ? parseInt(ranks.pbars) : null,
   683→    hBar: ranks.hbar ? parseInt(ranks.hbar) : null,
   684→    team: ranks.team ? parseInt(ranks.team) : null,
   685→  }) : null;
   686→
   687→  const roster = dashboard?.roster?.map(r => ({
   688→    id: r.id,
   689→    fullName: `${r.fname?.trim() || ''} ${r.lname?.trim() || ''}`.trim(),
   690→    hometown: r.hometown || '',
   691→    year: r.school_year ? parseInt(r.school_year) : null,
   692→  })) || [];
   693→
   694→  const hasData = staff.length > 0 || Object.keys(links).length > 0 || rankings || roster.length > 0;
   695→
   696→  if (!hasData) {
   697→    return (
   698→      <div className="text-center py-6 text-zinc-500">
   699→        <p>No data found for "{teamName}" ({gender === 'womens' ? "Women's" : "Men's"})</p>
   700→        <p className="text-xs mt-1">Try a different team name or check spelling</p>
   701→      </div>
   702→    );
   703→  }
   704→
   705→  return (
   706→    <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
   707→      {/* Coaching Staff */}
   708→      <div className="bg-zinc-800/50 rounded-lg p-4">
   709→        <h3 className="text-sm font-semibold text-white mb-3 flex items-center gap-2">
   710→          <UserGroupIcon className="w-4 h-4 text-cyan-500" />
   711→          Coaching Staff ({staff.length})
   712→        </h3>
   713→        {staff.length > 0 ? (
   714→          <div className="space-y-2">
   715→            {staff.map((coach) => (
   716→              <div key={coach.id} className="flex items-center gap-3 p-2 bg-zinc-700/50 rounded">
   717→                <div className="w-10 h-10 bg-zinc-600 rounded-full flex items-center justify-center overflow-hidden flex-shrink-0">
   718→                  {coach.imageUrl ? (
   719→                    <img src={coach.imageUrl} alt={coach.fullName} className="w-10 h-10 object-cover" />
   720→                  ) : (
   721→                    <UserGroupIcon className="w-5 h-5 text-zinc-400" />
   722→                  )}
   723→                </div>
   724→                <div className="flex-1 min-w-0">
   725→                  <div className="text-sm font-medium text-white truncate">{coach.fullName}</div>
   726→                  <div className="text-xs text-zinc-400">{coach.position}</div>
   727→                </div>
   728→              </div>
   729→            ))}
   730→          </div>
   731→        ) : (
   732→          <p className="text-zinc-500 text-sm">No coaching staff found</p>
   733→        )}
   734→      </div>
   735→
   736→      {/* Rankings */}
   737→      <div className="bg-zinc-800/50 rounded-lg p-4">
   738→        <h3 className="text-sm font-semibold text-white mb-3 flex items-center gap-2">
   739→          <TrophyIcon className="w-4 h-4 text-yellow-500" />
   740→          National Rankings
   741→        </h3>
   742→        {rankings ? (
   743→          <div className="grid grid-cols-2 gap-2">
   744→            {gender === 'womens' ? (
   745→              <>
   746→                <RankBadge label="Team" rank={rankings.team} />
   747→                <RankBadge label="Vault" rank={rankings.vault} />
   748→                <RankBadge label="Bars" rank={rankings.bars} />
   749→                <RankBadge label="Beam" rank={rankings.beam} />
   750→                <RankBadge label="Floor" rank={rankings.floor} />
   751→              </>
   752→            ) : (
   753→              <>
   754→                <RankBadge label="Team" rank={rankings.team} />
   755→                <RankBadge label="Floor" rank={rankings.floor} />
   756→                <RankBadge label="Pommel" rank={rankings.pommel} />
   757→                <RankBadge label="Rings" rank={rankings.rings} />
   758→                <RankBadge label="Vault" rank={rankings.vault} />
   759→                <RankBadge label="P-Bars" rank={rankings.pBars} />
   760→                <RankBadge label="H-Bar" rank={rankings.hBar} />
   761→              </>
   762→            )}
   763→          </div>
   764→        ) : (
   765→          <p className="text-zinc-500 text-sm">No rankings available</p>
   766→        )}
   767→      </div>
   768→
   769→      {/* Social Links */}
   770→      <div className="bg-zinc-800/50 rounded-lg p-4">
   771→        <h3 className="text-sm font-semibold text-white mb-3 flex items-center gap-2">
   772→          <LinkIcon className="w-4 h-4 text-blue-500" />
   773→          Social & Links
   774→        </h3>
   775→        {Object.keys(links).length > 0 ? (
   776→          <div className="space-y-2">
   777→            {links.officialSite && (
   778→              <SocialLink label="Official Site" url={links.officialSite} />
   779→            )}
   780→            {links.twitter && (
   781→              <SocialLink label="Twitter/X" url={links.twitter} />
   782→            )}
   783→            {links.instagram && (
   784→              <SocialLink label="Instagram" url={links.instagram} />
   785→            )}
   786→            {links.facebook && (
   787→              <SocialLink label="Facebook" url={links.facebook} />
   788→            )}
   789→          </div>
   790→        ) : (
   791→          <p className="text-zinc-500 text-sm">No social links found</p>
   792→        )}
   793→      </div>
   794→
   795→      {/* RTN Roster */}
   796→      <div className="bg-zinc-800/50 rounded-lg p-4">
   797→        <h3 className="text-sm font-semibold text-white mb-3 flex items-center gap-2">
   798→          <UserGroupIcon className="w-4 h-4 text-green-500" />
   799→          RTN Roster ({roster.length} athletes)
   800→        </h3>
   801→        {roster.length > 0 ? (
   802→          <div className="max-h-48 overflow-y-auto space-y-1">
   803→            {roster.map((athlete) => (
   804→              <div key={athlete.id} className="flex items-center justify-between p-1.5 bg-zinc-700/30 rounded text-xs">
   805→                <span className="text-zinc-200">{athlete.fullName}</span>
   806→                <span className="text-zinc-500">
   807→                  {athlete.year ? `Yr ${athlete.year}` : ''} {athlete.hometown && `• ${athlete.hometown}`}
   808→                </span>
   809→              </div>
   810→            ))}
   811→          </div>
   812→        ) : (
   813→          <p className="text-zinc-500 text-sm">No roster found</p>
   814→        )}
   815→      </div>
   816→    </div>
   817→  );
   818→}
   819→
   820→function RankBadge({ label, rank }) {
