    39→const CONFIDENCE = {
    40→  HIGH: 'high',       // 0.8-1.0 - Standard for all meets of this type
    41→  MEDIUM: 'medium',   // 0.5-0.79 - Common but optional
    42→  LOW: 'low',         // 0.2-0.49 - Contextual, based on specific meet details
    43→};
    44→
    45→// Confidence scoring factors - multipliers and bonuses for different context signals
    46→const CONFIDENCE_FACTORS = {
    47→  // Base confidence for having data
    48→  HAS_ROSTER_DATA: 0.1,        // Bonus when roster data is available
    49→  HAS_TEAM_STATS: 0.1,         // Bonus when team stats are available
    50→  HAS_DATE_INFO: 0.05,         // Bonus when date/season info is available
    51→
    52→  // Context-based adjustments
    53→  CHAMPIONSHIP_MEET: 0.15,     // Bonus for championship meets (higher stakes = more segments)
    54→  LATE_SEASON: 0.1,            // Bonus for late season (more storylines)
    55→  CLOSE_MATCHUP: 0.1,          // Bonus when teams are evenly matched (more drama)
    56→
    57→  // Special segment modifiers
    58→  SENIOR_COUNT_THRESHOLD: 3,   // Min seniors to strongly suggest senior segment
    59→  ALL_AMERICAN_BOOST: 0.15,    // Bonus when All-Americans are competing
    60→  MILESTONE_BOOST: 0.1,        // Bonus when athletes have upcoming milestones
    61→};
    62→
    63→// ============================================================================
    64→// Confidence Scoring Helpers
    65→// ============================================================================
    66→
    67→/**
    68→ * Calculate a confidence level string from a numeric score
    69→ * @param {number} score - Numeric confidence score (0-1)
    70→ * @returns {string} Confidence level (high, medium, low)
    71→ */
    72→function getConfidenceLevel(score) {
    73→  if (score >= 0.8) return CONFIDENCE.HIGH;
    74→  if (score >= 0.5) return CONFIDENCE.MEDIUM;
    75→  return CONFIDENCE.LOW;
    76→}
    77→
    78→/**
    79→ * Calculate dynamic confidence based on context signals
    80→ *
    81→ * @param {number} baseConfidence - Base confidence score (0-1)
    82→ * @param {Object} context - Competition context with metadata
    83→ * @param {Object} factors - Specific factors to apply for this segment type
    84→ * @returns {Object} { confidence: number, confidenceLevel: string, reasons: string[] }
    85→ */
    86→function calculateDynamicConfidence(baseConfidence, context, factors = {}) {
    87→  let confidence = baseConfidence;
    88→  const reasons = [];
    89→
    90→  // Data availability bonuses
    91→  if (factors.requiresRoster && context.teams?.some(t => t.roster?.length > 0)) {
    92→    confidence += CONFIDENCE_FACTORS.HAS_ROSTER_DATA;
    93→    reasons.push('Roster data available');
    94→  }
    95→
    96→  if (factors.requiresStats && context.statsAnalysis?.teamStats?.some(t => t.hasStats)) {
    97→    confidence += CONFIDENCE_FACTORS.HAS_TEAM_STATS;
    98→    reasons.push('Team statistics available');
    99→  }
   100→
   101→  if (context.dateInfo) {
   102→    confidence += CONFIDENCE_FACTORS.HAS_DATE_INFO;
   103→
   104→    // Season phase adjustments
   105→    if (context.dateInfo.seasonPhase === 'championship') {
   106→      confidence += CONFIDENCE_FACTORS.CHAMPIONSHIP_MEET;
   107→      reasons.push('Championship meet - high stakes');
   108→    } else if (context.dateInfo.seasonPhase === 'late') {
   109→      confidence += CONFIDENCE_FACTORS.LATE_SEASON;
   110→      reasons.push('Late season - playoff implications');
   111→    }
   112→  }
   113→
   114→  // Matchup analysis adjustments
   115→  if (context.statsAnalysis?.matchupNotes?.length > 0) {
   116→    const isCloseMatchup = context.statsAnalysis.matchupNotes.some(
   117→      n => n.includes('Close matchup') || n.includes('Very close')
   118→    );
   119→    if (isCloseMatchup) {
   120→      confidence += CONFIDENCE_FACTORS.CLOSE_MATCHUP;
   121→      reasons.push('Close matchup expected');
   122→    }
   123→  }
   124→
   125→  // Special segment boosts
   126→  if (factors.athleteFeature) {
   127→    if (context.allAmericans?.length > 0) {
   128→      confidence += CONFIDENCE_FACTORS.ALL_AMERICAN_BOOST;
   129→      reasons.push(`${context.allAmericans.length} All-American(s) competing`);
   130→    }
   131→    if (context.milestones?.upcoming?.length > 0) {
   132→      confidence += CONFIDENCE_FACTORS.MILESTONE_BOOST;
   133→      reasons.push('Athletes approaching milestones');
   134→    }
   135→  }
   136→
   137→  // Senior-specific boosts
   138→  if (factors.seniorFeature && context.seniors?.length >= CONFIDENCE_FACTORS.SENIOR_COUNT_THRESHOLD) {
   139→    const seniorsWithStorylines = context.seniors.filter(s => s.hasStorylines).length;
   140→    if (seniorsWithStorylines > 0) {
   141→      confidence += 0.1;
   142→      reasons.push(`${seniorsWithStorylines} senior(s) with notable storylines`);
   143→    }
   144→  }
   145→
   146→  // Cap at 1.0
   147→  confidence = Math.min(1.0, confidence);
   148→
   149→  return {
   150→    confidence: Math.round(confidence * 100) / 100,
   151→    confidenceLevel: getConfidenceLevel(confidence),
   152→    reasons,
   153→  };
   154→}
   155→
   156→/**
   157→ * Build a detailed reason string for a segment suggestion
   158→ *
   159→ * @param {string} baseReason - Base reason for the segment
   160→ * @param {Array} additionalReasons - Additional context-based reasons
   161→ * @returns {string} Combined reason string
   162→ */
   163→function buildReasonString(baseReason, additionalReasons = []) {
   164→  if (additionalReasons.length === 0) return baseReason;
   165→  return `${baseReason}. Context: ${additionalReasons.join('; ')}`;
   166→}
