   398→/**
   399→ * Get rotation segments based on competition type
   400→ */
   401→function getRotationSegments(context) {
   402→  const { gender, teamCount, teams, statsAnalysis, dateInfo } = context;
   403→  const events = gender === 'mens' ? MENS_EVENTS : WOMENS_EVENTS;
   404→  const eventCodes = gender === 'mens' ? MENS_EVENT_CODES : WOMENS_EVENT_CODES;
   405→  const rotationCount = events.length;
   406→
   407→  const segments = [];
   408→
   409→  // Determine if this is a close matchup (affects segment confidence)
   410→  const isCloseMatchup = statsAnalysis?.matchupNotes?.some(
   411→    n => n.includes('Close matchup') || n.includes('Very close')
   412→  );
   413→
   414→  for (let rotation = 1; rotation <= rotationCount; rotation++) {
   415→    // Rotation summary graphic - higher confidence for later rotations in close meets
   416→    const summaryBaseConf = rotation === 1 ? 0.85 : (isCloseMatchup ? 0.9 : 0.8);
   417→    const summaryConf = calculateDynamicConfidence(summaryBaseConf, context, { requiresStats: true });
   418→
   419→    segments.push({
   420→      id: `template-rotation-${rotation}-summary`,
   421→      name: `Rotation ${rotation} Summary`,
   422→      type: SEGMENT_TYPES.STATIC,
   423→      duration: 15,
   424→      scene: 'Graphics Fullscreen',
   425→      graphic: {
   426→        graphicId: 'event-summary',
   427→        params: {
   428→          summaryMode: 'rotation',
   429→          summaryRotation: rotation,
   430→        }
   431→      },
   432→      timingMode: 'fixed',
   433→      notes: `Display Rotation ${rotation} preview`,
   434→      confidence: summaryConf.confidence,
   435→      confidenceLevel: summaryConf.confidenceLevel,
   436→      category: 'rotation',
   437→      reason: buildReasonString('Standard rotation intro', summaryConf.reasons),
   438→    });
   439→
   440→    // Competition action for this rotation
   441→    // For dual meets, teams alternate apparatus
   442→    const actionConf = calculateDynamicConfidence(0.95, context, {});
   443→    if (teamCount === 2) {
   444→      // Home team event
   445→      const homeEventIndex = (rotation - 1) % events.length;
   446→      const awayEventIndex = (homeEventIndex + 1) % events.length;
   447→
   448→      segments.push({
   449→        id: `template-rotation-${rotation}-action`,
   450→        name: `Rotation ${rotation} - Competition`,
   451→        type: SEGMENT_TYPES.LIVE,
   452→        duration: null, // Manual advance
   453→        scene: 'Dual View',
   454→        graphic: null,
   455→        timingMode: 'manual',
   456→        notes: `${teams[0]?.name || 'Home'} on ${events[homeEventIndex]}, ${teams[1]?.name || 'Away'} on ${events[awayEventIndex]}`,
   457→        confidence: actionConf.confidence,
   458→        confidenceLevel: actionConf.confidenceLevel,
   459→        category: 'rotation',
   460→        reason: buildReasonString('Main competition segment', actionConf.reasons),
   461→      });
   462→    } else {
   463→      // Multi-team meet - all teams compete simultaneously
   464→      segments.push({
   465→        id: `template-rotation-${rotation}-action`,
   466→        name: `Rotation ${rotation} - Competition`,
   467→        type: SEGMENT_TYPES.LIVE,
   468→        duration: null,
   469→        scene: teamCount > 2 ? 'Quad View' : 'Dual View',
   470→        graphic: null,
   471→        timingMode: 'manual',
   472→        notes: `All teams compete on assigned apparatus`,
   473→        confidence: actionConf.confidence,
   474→        confidenceLevel: actionConf.confidenceLevel,
   475→        category: 'rotation',
   476→        reason: buildReasonString('Main competition segment', actionConf.reasons),
   477→      });
   478→    }
   479→
   480→    // Rotation scores - higher confidence for close matchups (more drama)
   481→    const scoresBaseConf = isCloseMatchup ? 0.9 : 0.8;
   482→    const scoresConf = calculateDynamicConfidence(scoresBaseConf, context, { requiresStats: true });
   483→
   484→    segments.push({
   485→      id: `template-rotation-${rotation}-scores`,
   486→      name: `Rotation ${rotation} Scores`,
   487→      type: SEGMENT_TYPES.STATIC,
   488→      duration: 20,
   489→      scene: 'Graphics Fullscreen',
   490→      graphic: { graphicId: 'scoreboard', params: {} },
   491→      timingMode: 'fixed',
   492→      notes: `Display scores after Rotation ${rotation}${isCloseMatchup ? ' - watch the margin' : ''}`,
   493→      confidence: scoresConf.confidence,
   494→      confidenceLevel: scoresConf.confidenceLevel,
   495→      category: 'rotation',
   496→      reason: buildReasonString('Score update after rotation', scoresConf.reasons),
   497→    });
   498→
   499→    // Commercial break between rotations (except last)
   500→    // Lower confidence for championship meets (often no commercial breaks)
   501→    if (rotation < rotationCount) {
   502→      const breakBaseConf = dateInfo?.seasonPhase === 'championship' ? 0.5 : 0.65;
   503→      const breakConf = calculateDynamicConfidence(breakBaseConf, context, {});
   504→
   505→      segments.push({
   506→        id: `template-rotation-${rotation}-break`,
   507→        name: 'Commercial Break',
   508→        type: SEGMENT_TYPES.BREAK,
   509→        duration: 120,
   510→        scene: 'Starting Soon',
   511→        graphic: null,
   512→        timingMode: 'fixed',
   513→        notes: 'Commercial break between rotations',
   514→        confidence: breakConf.confidence,
   515→        confidenceLevel: breakConf.confidenceLevel,
   516→        category: 'break',
   517→        reason: buildReasonString('Optional break between rotations', breakConf.reasons),
   518→      });
   519→    }
   520→
   521→    // Mid-meet analysis - after rotation 3 in 6-rotation meets or rotation 2 in 4-rotation meets
   522→    const midPoint = rotationCount === 6 ? 3 : 2;
   523→    if (rotation === midPoint && isCloseMatchup) {
   524→      const analysisConf = calculateDynamicConfidence(0.55, context, { requiresStats: true });
   525→
   526→      segments.push({
   527→        id: `template-rotation-${rotation}-analysis`,
   528→        name: 'Mid-Meet Analysis',
   529→        type: SEGMENT_TYPES.LIVE,
   530→        duration: 45,
   531→        scene: 'Talent Camera',
   532→        graphic: { graphicId: 'scoreboard', params: {} },
   533→        timingMode: 'fixed',
   534→        notes: 'Talent discusses the meet so far and what to watch in second half',
   535→        confidence: analysisConf.confidence,
   536→        confidenceLevel: analysisConf.confidenceLevel,
   537→        category: 'rotation',
   538→        reason: buildReasonString('Close matchup - mid-meet analysis adds value', analysisConf.reasons),
   539→      });
   540→    }
   541→  }
   542→
   543→  return segments;
   544→}
