   836→/**
   837→ * Parse competition type to extract gender and team count
   838→ */
   839→function parseCompetitionType(compType) {
   840→  if (!compType) return { gender: 'womens', teamCount: 2 };
   841→
   842→  const parts = compType.toLowerCase().split('-');
   843→  const gender = parts[0] === 'mens' ? 'mens' : 'womens';
   844→
   845→  let teamCount = 2;
   846→  if (parts[1]) {
   847→    const typeMap = { dual: 2, tri: 3, quad: 4, '5': 5, '6': 6 };
   848→    teamCount = typeMap[parts[1]] || 2;
   849→  }
   850→
   851→  return { gender, teamCount };
   852→}
   853→
   854→/**
   855→ * Parse meet date string into structured date info
   856→ * Handles formats like "January 17, 2026" or "Jan 17, 2026"
   857→ */
   858→function parseMeetDate(meetDateStr) {
   859→  if (!meetDateStr) return null;
   860→
   861→  try {
   862→    const date = new Date(meetDateStr);
   863→    if (isNaN(date.getTime())) return null;
   864→
   865→    const month = date.getMonth(); // 0-11
   866→    const dayOfWeek = date.getDay(); // 0=Sunday
   867→    const dayOfMonth = date.getDate();
   868→
   869→    // Determine season context (NCAA gymnastics season is typically Jan-April)
   870→    let seasonPhase = 'regular';
   871→    if (month === 0 && dayOfMonth <= 15) {
   872→      seasonPhase = 'early'; // Early January - season opener territory
   873→    } else if (month === 2 && dayOfMonth >= 15) {
   874→      seasonPhase = 'late'; // Late March - conference/NCAA championship territory
   875→    } else if (month >= 3) {
   876→      seasonPhase = 'championship'; // April - NCAA championships
   877→    }
   878→
   879→    return {
   880→      date,
   881→      month,
   882→      dayOfWeek,
   883→      dayOfMonth,
   884→      year: date.getFullYear(),
   885→      seasonPhase,
   886→      isWeekend: dayOfWeek === 0 || dayOfWeek === 5 || dayOfWeek === 6, // Fri, Sat, Sun
   887→      formatted: meetDateStr,
   888→    };
   889→  } catch (e) {
   890→    return null;
   891→  }
   892→}
