   922→/**
   923→ * Analyze team statistics for matchup context
   924→ */
   925→function analyzeTeamStats(competitionConfig, teams) {
   926→  const analysis = {
   927→    teamStats: [],
   928→    matchupNotes: [],
   929→    favorite: null,
   930→    margin: null,
   931→  };
   932→
   933→  teams.forEach((team, index) => {
   934→    const slot = team.slot;
   935→    const avg = parseFloat(competitionConfig?.[`team${slot}Ave`]) || 0;
   936→    const high = parseFloat(competitionConfig?.[`team${slot}High`]) || 0;
   937→    const tricode = competitionConfig?.[`team${slot}Tricode`] || '';
   938→
   939→    analysis.teamStats.push({
   940→      name: team.name,
   941→      slot,
   942→      tricode,
   943→      seasonAverage: avg,
   944→      seasonHigh: high,
   945→      hasStats: avg > 0,
   946→    });
   947→  });
   948→
   949→  // Determine favorite if stats available for both teams in a dual meet
   950→  if (analysis.teamStats.length === 2) {
   951→    const [team1, team2] = analysis.teamStats;
   952→    if (team1.hasStats && team2.hasStats) {
   953→      const diff = team1.seasonAverage - team2.seasonAverage;
   954→      if (Math.abs(diff) >= 1.0) {
   955→        analysis.favorite = diff > 0 ? team1.name : team2.name;
   956→        analysis.margin = Math.abs(diff).toFixed(3);
   957→        analysis.matchupNotes.push(
   958→          `${analysis.favorite} favored by ~${analysis.margin} points based on season averages`
   959→        );
   960→      } else if (Math.abs(diff) >= 0.5) {
   961→        analysis.matchupNotes.push('Close matchup expected - teams within 1 point average');
   962→      } else {
   963→        analysis.matchupNotes.push('Very close matchup - teams nearly even on paper');
   964→      }
   965→    }
   966→  }
   967→
   968→  return analysis;
   969→}
