  1101→    records: [],        // Record holders competing
  1102→  };
  1103→
  1104→  if (!db) return milestones;
  1105→
  1106→  try {
  1107→    // Check if milestones database exists
  1108→    const milestonesSnapshot = await db.ref('teamsDatabase/milestones').once('value');
  1109→    const milestonesData = milestonesSnapshot.val();
  1110→
  1111→    if (!milestonesData) {
