  1113→      // Future: compute from historical meet data or integrate with external API
  1114→      return milestones;
  1115→    }
  1116→
  1117→    // Build a set of athlete names from competing teams
  1118→    const competingAthletes = new Map();
  1119→    teams.forEach(team => {
  1120→      const roster = team.roster || [];
  1121→      roster.forEach(athlete => {
  1122→        const key = athlete.fullName?.toLowerCase() ||
  1123→          `${athlete.firstName} ${athlete.lastName}`.toLowerCase();
  1124→        competingAthletes.set(key, { ...athlete, team: team.name, teamSlot: team.slot });
  1125→      });
  1126→    });
  1127→
  1128→    // Find milestones for competing athletes
  1129→    Object.entries(milestonesData).forEach(([key, milestoneData]) => {
  1130→      if (competingAthletes.has(key)) {
  1131→        const athlete = competingAthletes.get(key);
  1132→        const athleteMilestones = milestoneData.milestones || [];
  1133→
  1134→        if (athleteMilestones.length > 0) {
  1135→          const athleteEntry = {
  1136→            name: athlete.fullName || `${athlete.firstName} ${athlete.lastName}`,
  1137→            firstName: athlete.firstName,
  1138→            lastName: athlete.lastName,
  1139→            team: athlete.team,
  1140→            teamSlot: athlete.teamSlot,
  1141→            milestones: athleteMilestones,
  1142→          };
  1143→
  1144→          // Categorize milestones
  1145→          const recordMilestones = athleteMilestones.filter(m =>
  1146→            m.type === 'event_record' || m.type === 'school_record' || m.type === 'conference_record'
  1147→          );
  1148→
  1149→          const upcomingMilestones = athleteMilestones.filter(m =>
  1150→            m.type === 'approaching' || m.approaching === true
  1151→          );
  1152→
  1153→          if (recordMilestones.length > 0) {
  1154→            milestones.records.push({
  1155→              ...athleteEntry,
  1156→              recordMilestones,
  1157→            });
  1158→          }
  1159→
  1160→          if (upcomingMilestones.length > 0) {
  1161→            milestones.upcoming.push({
  1162→              ...athleteEntry,
  1163→              upcomingMilestones,
  1164→            });
  1165→          }
  1166→
  1167→          milestones.athletes.push(athleteEntry);
  1168→        }
  1169→      }
  1170→    });
  1171→
  1172→    return milestones;
  1173→  } catch (error) {
  1174→    console.warn('[AISuggestionService] Error querying milestones:', error.message);
  1175→    return milestones;
  1176→  }
  1177→}
  1178→
  1179→/**
  1180→ * Compute potential milestones for seniors
  1181→ *
  1182→ * For seniors in their final season, compute potential story angles:
  1183→ * - Final home meet (if at home venue)
  1184→ * - Final conference championship
  1185→ * - Final NCAA championship appearance
  1186→ *
  1187→ * @param {Array} seniors - List of seniors from extractSeniors()
  1188→ * @param {Object} context - Competition context
  1189→ * @returns {Array} Enhanced senior data with potential storylines
  1190→ */
  1191→function computeSeniorMilestones(seniors, context) {
  1192→  const { dateInfo, venue, location, eventName } = context;
  1193→  const enhancedSeniors = [];
  1194→
  1195→  seniors.forEach(senior => {
  1196→    const storylines = [];
  1197→
  1198→    // Check if this is a championship meet
  1199→    const eventNameLower = eventName?.toLowerCase() || '';
  1200→    const isConferenceChamp = eventNameLower.includes('championship') &&
  1201→      (eventNameLower.includes('conference') || eventNameLower.includes('pac-12') ||
  1202→       eventNameLower.includes('big ten') || eventNameLower.includes('sec') ||
  1203→       eventNameLower.includes('big 12') || eventNameLower.includes('ncga'));
  1204→    const isNCAA = eventNameLower.includes('ncaa');
  1205→    const isNationals = eventNameLower.includes('national');
  1206→
  1207→    if (isNCAA || isNationals) {
  1208→      storylines.push({
  1209→        type: 'final_nationals',
  1210→        description: `Final NCAA/National Championship appearance for ${senior.firstName}`,
  1211→        significance: 'high',
  1212→      });
  1213→    } else if (isConferenceChamp) {
  1214→      storylines.push({
  1215→        type: 'final_conference',
  1216→        description: `Final conference championship for ${senior.firstName}`,
  1217→        significance: 'high',
  1218→      });
  1219→    }
  1220→
  1221→    // Check if late season (potential last regular season home meet)
  1222→    if (dateInfo?.seasonPhase === 'late' && dateInfo?.isWeekend) {
  1223→      storylines.push({
  1224→        type: 'potential_final_home',
  1225→        description: `Could be final home meet for ${senior.firstName}`,
  1226→        significance: 'medium',
  1227→      });
  1228→    }
  1229→
  1230→    enhancedSeniors.push({
  1231→      ...senior,
  1232→      storylines,
  1233→      hasStorylines: storylines.length > 0,
  1234→    });
  1235→  });
  1236→
  1237→  // Sort by those with storylines first, then alphabetically
  1238→  return enhancedSeniors.sort((a, b) => {
  1239→    if (a.hasStorylines !== b.hasStorylines) {
  1240→      return b.hasStorylines ? 1 : -1;
  1241→    }
  1242→    return a.name.localeCompare(b.name);
  1243→  });
  1244→}
  1245→
  1246→/**
  1247→ * Build context object from competition config and team data
  1248→ *
  1249→ * @param {Object} competitionConfig - Competition configuration from Firebase
  1250→ * @param {Object} teamsData - Teams database data
  1251→ * @param {Object} teamDataFromComp - Competition-specific team data with rosters
  1252→ * @param {Object} db - Firebase database reference (optional, for async queries)
  1253→ * @returns {Promise<Object>|Object} Context object (async if db provided)
  1254→ */
  1255→async function buildContext(competitionConfig, teamsData, teamDataFromComp, db = null) {
  1256→  const { gender, teamCount } = parseCompetitionType(competitionConfig?.compType);
  1257→
  1258→  // Extract team info from config
  1259→  const teams = [];
  1260→  for (let i = 1; i <= 6; i++) {
  1261→    const teamKey = competitionConfig?.[`team${i}Key`];
  1262→    const teamName = competitionConfig?.[`team${i}Name`];
  1263→
  1264→    if (teamName) {
  1265→      // Use competition's teamData which has richer roster info
  1266→      const compTeamData = teamDataFromComp?.[`team${i}`] || {};
  1267→      const fallbackTeamData = teamsData?.[teamKey] || {};
  1268→
  1269→      teams.push({
  1270→        slot: i,
  1271→        key: teamKey,
  1272→        name: teamName,
  1273→        logo: competitionConfig?.[`team${i}Logo`],
  1274→        // Prefer competition teamData roster, fallback to teamsDatabase
  1275→        roster: compTeamData.roster || fallbackTeamData.roster || [],
  1276→        coaches: competitionConfig?.[`team${i}Coaches`]?.split('\n').filter(Boolean) || [],
  1277→        rankings: compTeamData.rankings || {},
  1278→      });
  1279→    }
  1280→  }
  1281→
  1282→  // Parse meet date for date-based suggestions
  1283→  const dateInfo = parseMeetDate(competitionConfig?.meetDate);
  1284→
  1285→  // Extract seniors from team roster data (uses competition's teamData)
  1286→  const seniors = extractSeniors(teamDataFromComp, teams);
  1287→
  1288→  // Analyze team statistics
  1289→  const statsAnalysis = analyzeTeamStats(competitionConfig, teams);
  1290→
  1291→  // Count athletes by class year
  1292→  const classCounts = countByClassYear(teamDataFromComp, teams);
  1293→
  1294→  // Build base context
  1295→  const baseContext = {
  1296→    compId: competitionConfig?.compId,
  1297→    eventName: competitionConfig?.eventName,
  1298→    meetDate: competitionConfig?.meetDate,
  1299→    dateInfo,
  1300→    venue: competitionConfig?.venue,
  1301→    location: competitionConfig?.location,
  1302→    gender,
  1303→    teamCount: teams.length || teamCount,
  1304→    teams,
  1305→    team1Name: teams[0]?.name || 'Team 1',
  1306→    team2Name: teams[1]?.name || 'Team 2',
  1307→    // Class year analysis
  1308→    classCounts,
  1309→    // Team statistics
  1310→    statsAnalysis,
  1311→  };
  1312→
  1313→  // Query All-Americans and milestones if database available
  1314→  let allAmericans = [];
  1315→  let milestones = { athletes: [], upcoming: [], records: [] };
  1316→
  1317→  if (db) {
  1318→    // Run queries in parallel
  1319→    const [allAmericansResult, milestonesResult] = await Promise.all([
  1320→      queryAllAmericans(db, teams),
  1321→      queryMilestones(db, teams),
  1322→    ]);
  1323→    allAmericans = allAmericansResult;
  1324→    milestones = milestonesResult;
  1325→  }
  1326→
  1327→  // Compute senior storylines
  1328→  const seniorsWithStorylines = computeSeniorMilestones(seniors, baseContext);
  1329→
  1330→  return {
  1331→    ...baseContext,
  1332→    // Roster analysis with enhanced data
  1333→    seniors: seniorsWithStorylines,
  1334→    allAmericans,
  1335→    milestones,
  1336→  };
  1337→}
  1338→
  1339→// ============================================================================
  1340→// Main API
  1341→// ============================================================================
  1342→
  1343→/**
  1344→ * Generate segment suggestions for a competition
  1345→ *
  1346→ * @param {string} compId - Competition ID
  1347→ * @param {Object} options - Generation options
  1348→ * @param {boolean} options.includePreShow - Include pre-show segments (default: true)
  1349→ * @param {boolean} options.includeTeamIntros - Include team intro segments (default: true)
  1350→ * @param {boolean} options.includeRotations - Include rotation segments (default: true)
  1351→ * @param {boolean} options.includePostShow - Include post-show segments (default: true)
  1352→ * @param {boolean} options.includeSpecial - Include special segments (default: true)
  1353→ * @param {number} options.minConfidence - Minimum confidence threshold (default: 0.5)
  1354→ * @returns {Promise<Object>} Suggestions result
  1355→ */
  1356→async function generateSuggestions(compId, options = {}) {
  1357→  const {
  1358→    includePreShow = true,
  1359→    includeTeamIntros = true,
  1360→    includeRotations = true,
  1361→    includePostShow = true,
  1362→    includeSpecial = true,
  1363→    minConfidence = 0.5,
  1364→  } = options;
  1365→
  1366→  const db = getDb();
  1367→  if (!db) {
  1368→    return {
  1369→      success: false,
  1370→      error: 'Firebase not available',
  1371→      suggestions: [],
  1372→    };
  1373→  }
  1374→
  1375→  try {
  1376→    // Fetch competition config
  1377→    const configSnapshot = await db.ref(`competitions/${compId}/config`).once('value');
  1378→    const competitionConfig = configSnapshot.val();
  1379→
  1380→    if (!competitionConfig) {
  1381→      return {
  1382→        success: false,
  1383→        error: 'Competition not found',
  1384→        suggestions: [],
  1385→      };
  1386→    }
  1387→
  1388→    // Fetch teams database for roster info (fallback)
  1389→    const teamsSnapshot = await db.ref('teamsDatabase/teams').once('value');
  1390→    const teamsData = teamsSnapshot.val() || {};
  1391→
  1392→    // Fetch competition's teamData which has richer roster info (includes year, rankings, etc.)
  1393→    const teamDataSnapshot = await db.ref(`competitions/${compId}/teamData`).once('value');
  1394→    const teamDataFromComp = teamDataSnapshot.val() || {};
  1395→
  1396→    // Build context with full metadata analysis (pass db for All-American/milestone queries)
  1397→    const context = await buildContext(competitionConfig, teamsData, teamDataFromComp, db);
  1398→
  1399→    // Generate suggestions by category
  1400→    let suggestions = [];
  1401→
  1402→    if (includePreShow) {
  1403→      suggestions = suggestions.concat(getPreShowSegments(context));
  1404→    }
  1405→
  1406→    if (includeTeamIntros) {
  1407→      suggestions = suggestions.concat(getTeamIntroSegments(context));
  1408→    }
  1409→
  1410→    if (includeRotations) {
  1411→      suggestions = suggestions.concat(getRotationSegments(context));
  1412→    }
  1413→
  1414→    if (includePostShow) {
  1415→      suggestions = suggestions.concat(getPostShowSegments(context));
  1416→    }
  1417→
  1418→    if (includeSpecial) {
  1419→      suggestions = suggestions.concat(getSpecialSegments(context));
  1420→    }
  1421→
  1422→    // Filter by confidence threshold
  1423→    suggestions = suggestions.filter(s => s.confidence >= minConfidence);
  1424→
  1425→    // Add order indices
  1426→    suggestions = suggestions.map((s, index) => ({
  1427→      ...s,
  1428→      suggestedOrder: index + 1,
  1429→    }));
  1430→
  1431→    return {
  1432→      success: true,
  1433→      context: {
  1434→        compId,
  1435→        eventName: context.eventName,
  1436→        gender: context.gender,
  1437→        teamCount: context.teamCount,
  1438→        teams: context.teams.map(t => ({
  1439→          name: t.name,
  1440→          rosterSize: t.roster?.length || 0,
  1441→          rankings: t.rankings || {},
  1442→        })),
  1443→        // Enhanced metadata from Task 44
  1444→        dateInfo: context.dateInfo ? {
  1445→          formatted: context.dateInfo.formatted,
  1446→          seasonPhase: context.dateInfo.seasonPhase,
  1447→          isWeekend: context.dateInfo.isWeekend,
  1448→        } : null,
  1449→        venue: context.venue,
  1450→        location: context.location,
  1451→        statsAnalysis: {
  1452→          teamStats: context.statsAnalysis.teamStats,
  1453→          matchupNotes: context.statsAnalysis.matchupNotes,
  1454→          favorite: context.statsAnalysis.favorite,
  1455→        },
  1456→        // Roster analysis from Task 45
  1457→        seniors: context.seniors.map(s => ({
  1458→          name: s.name,
  1459→          team: s.team,
  1460→          hasStorylines: s.hasStorylines,
  1461→          storylines: s.storylines || [],
  1462→        })),
  1463→        allAmericans: context.allAmericans.map(a => ({
  1464→          name: a.name,
  1465→          team: a.team,
  1466→          honorCount: a.honorCount,
  1467→          mostRecent: a.mostRecent,
  1468→        })),
  1469→        milestones: {
  1470→          athleteCount: context.milestones?.athletes?.length || 0,
  1471→          upcomingCount: context.milestones?.upcoming?.length || 0,
  1472→          recordHolders: context.milestones?.records?.length || 0,
  1473→        },
  1474→        classCounts: context.classCounts,
  1475→      },
  1476→      suggestions,
  1477→      meta: {
  1478→        totalSuggestions: suggestions.length,
  1479→        byCategory: {
  1480→          'pre-show': suggestions.filter(s => s.category === 'pre-show').length,
  1481→          'team-intro': suggestions.filter(s => s.category === 'team-intro').length,
  1482→          'rotation': suggestions.filter(s => s.category === 'rotation').length,
  1483→          'post-show': suggestions.filter(s => s.category === 'post-show').length,
  1484→          'special': suggestions.filter(s => s.category === 'special').length,
  1485→          'break': suggestions.filter(s => s.category === 'break').length,
  1486→        },
  1487→        generatedAt: new Date().toISOString(),
  1488→      },
  1489→    };
  1490→  } catch (error) {
  1491→    console.error('[AISuggestionService] Error generating suggestions:', error);
  1492→    return {
  1493→      success: false,
  1494→      error: error.message,
  1495→      suggestions: [],
  1496→    };
  1497→  }
  1498→}
  1499→
  1500→/**
  1501→ * Get suggestions for a specific category
  1502→ */
  1503→async function getSuggestionsByCategory(compId, category) {
  1504→  const result = await generateSuggestions(compId, {
  1505→    includePreShow: category === 'pre-show' || category === 'all',
  1506→    includeTeamIntros: category === 'team-intro' || category === 'all',
  1507→    includeRotations: category === 'rotation' || category === 'all',
  1508→    includePostShow: category === 'post-show' || category === 'all',
  1509→    includeSpecial: category === 'special' || category === 'all',
  1510→  });
  1511→
  1512→  if (category !== 'all') {
  1513→    result.suggestions = result.suggestions.filter(s => s.category === category);
  1514→  }
  1515→
  1516→  return result;
  1517→}
  1518→
  1519→/**
  1520→ * Get a quick suggestion count without full generation
  1521→ */
  1522→async function getSuggestionCount(compId) {
  1523→  const db = getDb();
  1524→  if (!db) {
  1525→    return { count: 0, available: false };
  1526→  }
  1527→
  1528→  try {
  1529→    const configSnapshot = await db.ref(`competitions/${compId}/config`).once('value');
  1530→    const config = configSnapshot.val();
  1531→
  1532→    if (!config) {
  1533→      return { count: 0, available: false };
  1534→    }
  1535→
  1536→    const { gender, teamCount } = parseCompetitionType(config.compType);
  1537→    const events = gender === 'mens' ? MENS_EVENTS : WOMENS_EVENTS;
  1538→
  1539→    // Estimate suggestion count:
  1540→    // Pre-show (4) + Team intros (2 per team) + Rotations (3-4 per rotation) + Post-show (3) + Specials (0-2)
  1541→    const preShowCount = 4;
  1542→    const teamIntroCount = teamCount * 2;
  1543→    const rotationCount = events.length * 4; // summary + action + scores + break
  1544→    const postShowCount = 3;
  1545→
  1546→    return {
  1547→      count: preShowCount + teamIntroCount + rotationCount + postShowCount,
  1548→      available: true,
  1549→      gender,
  1550→      teamCount,
  1551→    };
  1552→  } catch (error) {
  1553→    return { count: 0, available: false, error: error.message };
  1554→  }
  1555→}
  1556→
  1557→// ============================================================================
  1558→// Export
  1559→// ============================================================================
  1560→
  1561→const aiSuggestionService = {
  1562→  generateSuggestions,
  1563→  getSuggestionsByCategory,
  1564→  getSuggestionCount,
  1565→  // Expose constants for testing
  1566→  SEGMENT_TYPES,
  1567→  CONFIDENCE,
  1568→  CONFIDENCE_FACTORS,
  1569→  MENS_EVENTS,
  1570→  WOMENS_EVENTS,
  1571→  // Expose helper functions for testing
  1572→  calculateDynamicConfidence,
  1573→  getConfidenceLevel,
  1574→  buildReasonString,
  1575→};
  1576→
  1577→export default aiSuggestionService;
  1578→
  1579→export {
  1580→  generateSuggestions,
  1581→  getSuggestionsByCategory,
  1582→  getSuggestionCount,
  1583→  SEGMENT_TYPES,
  1584→  CONFIDENCE,
  1585→  CONFIDENCE_FACTORS,
  1586→  MENS_EVENTS,
  1587→  WOMENS_EVENTS,
  1588→  calculateDynamicConfidence,
  1589→  getConfidenceLevel,
  1590→  buildReasonString,
  1591→};
