   227→  /**
   228→   * Update context based on current show state
   229→   *
   230→   * This is the main context generation loop. It:
   231→   * 1. Checks current segment
   232→   * 2. Queries for relevant context
   233→   * 3. Generates talking points
   234→   * 4. Broadcasts updates
   235→   */
   236→  async _updateContext() {
   237→    if (!this._isRunning) return;
   238→
   239→    try {
   240→      // Get current show state
   241→      const showState = this._getShowState();
   242→      if (!showState || showState.showState !== 'RUNNING') {
   243→        return;
   244→      }
   245→
   246→      const currentSegment = showState.currentSegment;
   247→      if (!currentSegment) return;
   248→
   249→      // Only regenerate if segment changed
   250→      if (currentSegment.id === this._lastSegmentId) {
   251→        return;
   252→      }
   253→
   254→      this._lastSegmentId = currentSegment.id;
   255→
   256→      // Generate context for this segment (stub - returns placeholder data)
   257→      const context = await this._generateSegmentContext(currentSegment);
   258→
   259→      // Store and broadcast
   260→      this._currentContext = context;
   261→      this._broadcastContext(context);
   262→    } catch (error) {
   263→      console.error(`[AIContextService] Error updating context:`, error);
   264→    }
   265→  }
