   389→  _getScoreBasedTalkingPoints(liveScores, segment) {
   390→    const points = [];
   391→
   392→    // Add team standings talking point
   393→    if (liveScores.teams?.length >= 2) {
   394→      const [leader, second] = liveScores.teams;
   395→      const margin = ((leader.score || 0) - (second.score || 0)).toFixed(3);
   396→
   397→      if (margin > 0) {
   398→        points.push({
   399→          id: `standings-${Date.now()}`,
   400→          type: CONTEXT_TYPES.SCORE,
   401→          priority: margin > 1 ? PRIORITY.MEDIUM : PRIORITY.HIGH,
   402→          text: `${leader.name} leads ${second.name} by ${margin} points`,
   403→          source: 'live-scores',
   404→          data: { leader, second, margin: parseFloat(margin) },
   405→        });
   406→      } else if (margin === '0.000') {
   407→        points.push({
   408→          id: `standings-tied-${Date.now()}`,
   409→          type: CONTEXT_TYPES.SCORE,
   410→          priority: PRIORITY.HIGH,
