  1013→  /**
  1014→   * Fetch live scores from Virtius API
  1015→   *
  1016→   * Caches results for `_virtiusCacheMs` milliseconds to avoid hammering the API.
  1017→   *
  1018→   * @param {boolean} forceRefresh - Force a fresh fetch, ignoring cache
  1019→   * @returns {Promise<Object>} Live score data with structure:
  1020→   *   {
  1021→   *     available: boolean,
  1022→   *     sessionId: string,
  1023→   *     meet: { name, date, location, sex },
  1024→   *     teams: [{ name, tricode, logo, score, rank }],
  1025→   *     currentRotation: number,
  1026→   *     eventResults: { [eventName]: { gymnasts: [...], teamScores: {...} } },
  1027→   *     recentScores: [{ athlete, team, event, score, timestamp }],
  1028→   *     fetchedAt: ISO timestamp
  1029→   *   }
  1030→   */
  1031→  async fetchLiveScores(forceRefresh = false) {
  1032→    // Check if we have a session ID
  1033→    if (!this._virtiusSessionId) {
  1034→      // Try to get it from competition config
  1035→      await this._loadVirtiusSessionId();
  1036→    }
  1037→
  1038→    if (!this._virtiusSessionId) {
  1039→      return {
  1040→        available: false,
  1041→        reason: 'no_session_id',
  1042→        message: 'No Virtius session ID configured for this competition',
  1043→      };
  1044→    }
  1045→
  1046→    // Check cache
  1047→    const now = Date.now();
  1048→    if (
  1049→      !forceRefresh &&
  1050→      this._virtiusData &&
  1051→      this._virtiusLastFetch &&
  1052→      now - this._virtiusLastFetch < this._virtiusCacheMs
  1053→    ) {
  1054→      return this._virtiusData;
  1055→    }
  1056→
  1057→    try {
  1058→      const data = await this._fetchVirtiusSession(this._virtiusSessionId);
  1059→      const parsedData = this._parseVirtiusData(data);
  1060→
  1061→      // Cache the parsed data
  1062→      this._virtiusData = parsedData;
  1063→      this._virtiusLastFetch = now;
  1064→
  1065→      console.log(`[AIContextService] Fetched live scores for session ${this._virtiusSessionId}`);
  1066→      return parsedData;
  1067→    } catch (error) {
  1068→      console.error(`[AIContextService] Error fetching Virtius data:`, error);
  1069→      return {
  1070→        available: false,
  1071→        reason: 'fetch_error',
  1072→        message: error.message,
  1073→        sessionId: this._virtiusSessionId,
  1074→      };
  1075→    }
  1076→  }
  1077→
  1078→  /**
  1079→   * Load Virtius session ID from competition config
  1080→   */
  1081→  async _loadVirtiusSessionId() {
  1082→    if (this._competitionConfig?.virtiusSessionId) {
  1083→      this._virtiusSessionId = this._competitionConfig.virtiusSessionId;
  1084→      return;
  1085→    }
  1086→
  1087→    // Try to load from Firebase
  1088→    const db = getDb();
  1089→    if (!db || !this.compId) return;
  1090→
  1091→    try {
  1092→      const snapshot = await db.ref(`competitions/${this.compId}/config/virtiusSessionId`).once('value');
  1093→      const sessionId = snapshot.val();
  1094→      if (sessionId) {
  1095→        this._virtiusSessionId = sessionId;
  1096→        console.log(`[AIContextService] Loaded Virtius session ID: ${sessionId}`);
  1097→      }
  1098→    } catch (error) {
  1099→      console.error(`[AIContextService] Error loading Virtius session ID:`, error);
  1100→    }
  1101→  }
  1102→
  1103→  /**
  1104→   * Fetch raw data from Virtius API
  1105→   *
  1106→   * @param {string} sessionId - Virtius session ID
  1107→   * @returns {Promise<Object>} Raw Virtius API response
  1108→   */
  1109→  async _fetchVirtiusSession(sessionId) {
  1110→    const url = `${VIRTIUS_API_BASE}/session/${sessionId}/json`;
  1111→
  1112→    const response = await fetch(url, {
  1113→      headers: {
  1114→        Accept: 'application/json',
  1115→      },
  1116→    });
  1117→
  1118→    if (!response.ok) {
  1119→      if (response.status === 404) {
  1120→        throw new Error(`Virtius session not found: ${sessionId}`);
  1121→      }
  1122→      throw new Error(`Virtius API error: ${response.status} ${response.statusText}`);
  1123→    }
  1124→
  1125→    return response.json();
  1126→  }
  1127→
  1128→  /**
  1129→   * Parse raw Virtius data into a structured format for the AI context
  1130→   *
  1131→   * @param {Object} rawData - Raw Virtius API response
  1132→   * @returns {Object} Parsed score data
  1133→   */
  1134→  _parseVirtiusData(rawData) {
  1135→    const meet = rawData.meet || {};
  1136→    const teams = meet.teams || [];
  1137→    const eventResults = meet.event_results || [];
  1138→
  1139→    // Parse teams with their current scores
  1140→    const parsedTeams = teams
  1141→      .sort((a, b) => (a.team_order || 0) - (b.team_order || 0))
  1142→      .map((team, index) => ({
  1143→        name: team.name || team.short_name,
  1144→        tricode: team.tricode,
  1145→        logo: team.logo,
  1146→        score: team.total_score || team.score || 0,
  1147→        rank: index + 1,
  1148→        teamOrder: team.team_order,
  1149→      }));
  1150→
  1151→    // Sort by score to get actual rankings
  1152→    const sortedByScore = [...parsedTeams].sort((a, b) => (b.score || 0) - (a.score || 0));
  1153→    sortedByScore.forEach((team, idx) => {
  1154→      team.rank = idx + 1;
  1155→    });
  1156→
  1157→    // Parse event results
  1158→    const parsedEventResults = {};
  1159→    for (const event of eventResults) {
  1160→      const eventName = event.event_name;
  1161→      const shortCode = EVENT_MAPPINGS.virtiusToShort[eventName] || eventName;
  1162→
  1163→      parsedEventResults[shortCode] = {
  1164→        eventName,
  1165→        displayName: EVENT_MAPPINGS.shortToDisplay[shortCode] || eventName,
  1166→        gymnasts: (event.gymnasts || []).map((g) => ({
  1167→          name: g.full_name || g.name,
  1168→          firstName: g.first_name,
  1169→          lastName: g.last_name,
  1170→          team: g.team || g.team_name,
  1171→          tricode: g.tricode,
  1172→          score: g.score || g.total_score,
  1173→          rank: g.rank || g.place,
  1174→          difficulty: g.d_score,
  1175→          execution: g.e_score,
  1176→          startValue: g.start_value,
  1177→          deductions: g.deductions,
  1178→        })),
  1179→        teamScores: {},
  1180→      };
  1181→
  1182→      // Aggregate team scores for this event
  1183→      for (const g of event.gymnasts || []) {
  1184→        const teamKey = g.tricode || g.team;
  1185→        if (teamKey && g.score) {
  1186→          if (!parsedEventResults[shortCode].teamScores[teamKey]) {
  1187→            parsedEventResults[shortCode].teamScores[teamKey] = {
  1188→              total: 0,
  1189→              count: 0,
  1190→              scores: [],
  1191→            };
  1192→          }
  1193→          parsedEventResults[shortCode].teamScores[teamKey].total += g.score;
  1194→          parsedEventResults[shortCode].teamScores[teamKey].count += 1;
  1195→          parsedEventResults[shortCode].teamScores[teamKey].scores.push(g.score);
  1196→        }
  1197→      }
  1198→    }
  1199→
  1200→    // Calculate current rotation based on event results
  1201→    const currentRotation = this._inferCurrentRotation(eventResults, teams.length);
  1202→
  1203→    // Get recent scores (last 5 scored routines across all events)
  1204→    const recentScores = this._extractRecentScores(eventResults);
  1205→
  1206→    return {
  1207→      available: true,
  1208→      sessionId: this._virtiusSessionId,
  1209→      meet: {
  1210→        name: meet.name,
  1211→        date: meet.date,
  1212→        location: meet.location,
  1213→        sex: meet.sex,
  1214→        gender: meet.sex === 'women' ? 'womens' : 'mens',
  1215→      },
  1216→      teams: parsedTeams,
  1217→      currentRotation,
  1218→      eventResults: parsedEventResults,
  1219→      recentScores,
  1220→      fetchedAt: new Date().toISOString(),
  1221→    };
  1222→  }
  1223→
  1224→  /**
  1225→   * Infer current rotation based on completed events
  1226→   *
  1227→   * @param {Array} eventResults - Event results from Virtius
  1228→   * @param {number} teamCount - Number of teams
  1229→   * @returns {number} Estimated current rotation (1-based)
  1230→   */
  1231→  _inferCurrentRotation(eventResults, teamCount) {
  1232→    // Count events with at least one score
  1233→    let eventsWithScores = 0;
  1234→    for (const event of eventResults) {
  1235→      const hasScores = (event.gymnasts || []).some((g) => g.score > 0);
  1236→      if (hasScores) eventsWithScores++;
  1237→    }
  1238→
  1239→    // For dual meets (2 teams), there are 6 rotations (men) or 4 rotations (women)
  1240→    // Each team does one event per rotation
  1241→    // So eventsWithScores roughly corresponds to rotations completed
  1242→    if (eventsWithScores === 0) return 1;
  1243→
  1244→    // If all events have scores, we're likely at the end
  1245→    if (eventsWithScores >= eventResults.length) {
  1246→      return eventResults.length;
  1247→    }
  1248→
  1249→    // Otherwise, estimate based on events completed
  1250→    return Math.min(eventsWithScores + 1, eventResults.length);
  1251→  }
  1252→
  1253→  /**
  1254→   * Extract recent scores from event results
  1255→   *
  1256→   * @param {Array} eventResults - Event results from Virtius
  1257→   * @returns {Array} Recent scores sorted by most recent first
  1258→   */
  1259→  _extractRecentScores(eventResults) {
  1260→    const allScores = [];
  1261→
  1262→    for (const event of eventResults) {
  1263→      const shortCode = EVENT_MAPPINGS.virtiusToShort[event.event_name] || event.event_name;
  1264→
  1265→      for (const g of event.gymnasts || []) {
  1266→        if (g.score > 0) {
  1267→          allScores.push({
  1268→            athlete: g.full_name || g.name,
  1269→            team: g.tricode || g.team,
  1270→            event: shortCode,
  1271→            eventDisplay: EVENT_MAPPINGS.shortToDisplay[shortCode] || event.event_name,
  1272→            score: g.score,
  1273→            rank: g.rank || g.place,
  1274→            // We don't have timestamps from Virtius, so use order in results
  1275→            order: g.rank || 999,
  1276→          });
  1277→        }
  1278→      }
  1279→    }
  1280→
  1281→    // Sort by event order (later events = more recent) then by rank
  1282→    // This is a heuristic since Virtius doesn't provide timestamps
  1283→    allScores.sort((a, b) => {
  1284→      // Scores are typically added in order, so later events are more recent
  1285→      return b.order - a.order;
  1286→    });
  1287→
  1288→    // Return last 10 scores
  1289→    return allScores.slice(0, 10);
  1290→  }
  1291→
  1292→  /**
  1293→   * Get current team standings from live scores
  1294→   *
  1295→   * @returns {Promise<Array>} Team standings array
