  1344→  /**
  1345→   * Check if a score is a career high for an athlete
  1346→   *
  1347→   * Compares against:
  1348→   * 1. Stored career bests in Firebase (athleteStats/{athleteId}/careerBests)
  1349→   * 2. Season bests from current show's score tracking
  1350→   * 3. Previous scores in current meet
  1351→   *
  1352→   * @param {string} athleteName - Athlete name
  1353→   * @param {string} event - Event code (FX, VT, etc.)
  1354→   * @param {number} score - Score to check
  1355→   * @returns {Promise<Object>} Career high check result
  1356→   */
  1357→  async checkCareerHigh(athleteName, event, score) {
  1358→    if (!athleteName || !event || typeof score !== 'number') {
  1359→      return { isCareerHigh: false, reason: 'invalid_input' };
  1360→    }
  1361→
  1362→    try {
  1363→      // Get athlete's stored career bests
  1364→      const careerBests = await this._getAthleteCareerBests(athleteName);
  1365→      const previousHigh = careerBests?.[event] || null;
  1366→
  1367→      // Check if this is a career high
  1368→      const isCareerHigh = previousHigh === null || score > previousHigh;
  1369→      const isSeasonHigh = await this._checkSeasonHigh(athleteName, event, score);
  1370→      const isMeetHigh = this._checkMeetHigh(athleteName, event, score);
  1371→
  1372→      // Determine the type of achievement
  1373→      let achievementType = null;
  1374→      if (isCareerHigh && previousHigh !== null) {
  1375→        achievementType = 'career_high';
  1376→      } else if (isSeasonHigh) {
  1377→        achievementType = 'season_high';
  1378→      } else if (isMeetHigh) {
  1379→        achievementType = 'meet_high';
  1380→      }
  1381→
  1382→      const result = {
  1383→        isCareerHigh: isCareerHigh && previousHigh !== null,
  1384→        isSeasonHigh,
  1385→        isMeetHigh,
  1386→        achievementType,
  1387→        previousHigh,
  1388→        improvement: previousHigh ? (score - previousHigh).toFixed(3) : null,
  1389→        score,
  1390→        event,
  1391→        athleteName,
  1392→      };
  1393→
  1394→      // If this is a notable achievement, store it and generate alert
  1395→      if (achievementType) {
  1396→        await this._recordAchievement(result);
  1397→      }
  1398→
  1399→      return result;
  1400→    } catch (error) {
  1401→      console.error(`[AIContextService] Error checking career high:`, error);
  1402→      return { isCareerHigh: false, error: error.message };
  1403→    }
  1404→  }
  1405→
  1406→  /**
  1407→   * Detect if a score breaks any records
  1408→   *
  1409→   * Checks against:
  1410→   * 1. School records (stored in Firebase)
  1411→   * 2. Meet records (if available)
  1412→   * 3. Venue records (if available)
  1413→   *
  1414→   * @param {string} athleteName - Athlete name
  1415→   * @param {string} event - Event code
  1416→   * @param {number} score - Score to check
  1417→   * @param {string} teamTricode - Team tricode for school record lookup
  1418→   * @returns {Promise<Object>} Record check result
  1419→   */
  1420→  async checkRecords(athleteName, event, score, teamTricode = null) {
  1421→    if (!athleteName || !event || typeof score !== 'number') {
  1422→      return { breaksRecord: false, reason: 'invalid_input' };
  1423→    }
  1424→
  1425→    const brokenRecords = [];
  1426→
  1427→    try {
  1428→      // Check school record
  1429→      const schoolRecord = await this._getSchoolRecord(teamTricode, event);
  1430→      if (schoolRecord && score > schoolRecord.score) {
  1431→        brokenRecords.push({
  1432→          type: 'school',
  1433→          previousScore: schoolRecord.score,
  1434→          previousHolder: schoolRecord.holder,
  1435→          previousDate: schoolRecord.date,
  1436→          improvement: (score - schoolRecord.score).toFixed(3),
  1437→        });
  1438→      }
  1439→
  1440→      // Check meet record (from current competition config)
  1441→      const meetRecord = await this._getMeetRecord(event);
  1442→      if (meetRecord && score > meetRecord.score) {
  1443→        brokenRecords.push({
  1444→          type: 'meet',
  1445→          previousScore: meetRecord.score,
  1446→          previousHolder: meetRecord.holder,
  1447→          previousYear: meetRecord.year,
  1448→          improvement: (score - meetRecord.score).toFixed(3),
  1449→        });
  1450→      }
  1451→
  1452→      // Check if this ties a record (within 0.001)
  1453→      const tiedRecords = [];
  1454→      if (schoolRecord && Math.abs(score - schoolRecord.score) < 0.001) {
  1455→        tiedRecords.push({ type: 'school', score: schoolRecord.score });
  1456→      }
  1457→      if (meetRecord && Math.abs(score - meetRecord.score) < 0.001) {
  1458→        tiedRecords.push({ type: 'meet', score: meetRecord.score });
  1459→      }
  1460→
  1461→      const result = {
  1462→        breaksRecord: brokenRecords.length > 0,
  1463→        tiesRecord: tiedRecords.length > 0,
  1464→        records: brokenRecords,
  1465→        tiedRecords,
  1466→        athleteName,
  1467→        event,
  1468→        score,
  1469→      };
  1470→
  1471→      // If a record is broken, record it
  1472→      if (brokenRecords.length > 0) {
  1473→        await this._recordBrokenRecord(result);
  1474→      }
  1475→
  1476→      return result;
  1477→    } catch (error) {
  1478→      console.error(`[AIContextService] Error checking records:`, error);
  1479→      return { breaksRecord: false, error: error.message };
  1480→    }
  1481→  }
  1482→
  1483→  /**
  1484→   * Scan recent scores for career highs and records
  1485→   * Called during context updates to detect achievements in live scores
  1486→   *
  1487→   * @returns {Promise<Array>} List of detected achievements
  1488→   */
  1489→  async scanForAchievements() {
  1490→    const achievements = [];
  1491→
  1492→    if (!this._virtiusData?.available || !this._virtiusData.recentScores) {
  1493→      return achievements;
  1494→    }
  1495→
  1496→    // Get team tricodes for record lookups
  1497→    const teamTricodes = this._virtiusData.teams?.map(t => t.tricode) || [];
  1498→
  1499→    for (const scoreData of this._virtiusData.recentScores) {
  1500→      // Skip if already processed
  1501→      const scoreKey = `${scoreData.athlete}-${scoreData.event}-${scoreData.score}`;
  1502→      if (this._processedScores?.has(scoreKey)) {
  1503→        continue;
  1504→      }
  1505→
  1506→      // Mark as processed
  1507→      if (!this._processedScores) {
  1508→        this._processedScores = new Set();
  1509→      }
  1510→      this._processedScores.add(scoreKey);
  1511→
  1512→      // Check for career high
  1513→      const careerResult = await this.checkCareerHigh(
  1514→        scoreData.athlete,
  1515→        scoreData.event,
  1516→        scoreData.score
  1517→      );
  1518→
  1519→      if (careerResult.achievementType) {
  1520→        achievements.push({
  1521→          type: careerResult.achievementType,
  1522→          ...careerResult,
  1523→          timestamp: new Date().toISOString(),
  1524→        });
  1525→      }
  1526→
  1527→      // Check for records
  1528→      const teamTricode = scoreData.team || teamTricodes[0];
  1529→      const recordResult = await this.checkRecords(
  1530→        scoreData.athlete,
  1531→        scoreData.event,
  1532→        scoreData.score,
  1533→        teamTricode
  1534→      );
  1535→
  1536→      if (recordResult.breaksRecord) {
  1537→        achievements.push({
  1538→          type: 'record_broken',
  1539→          ...recordResult,
  1540→          timestamp: new Date().toISOString(),
  1541→        });
  1542→      } else if (recordResult.tiesRecord) {
  1543→        achievements.push({
  1544→          type: 'record_tied',
  1545→          ...recordResult,
  1546→          timestamp: new Date().toISOString(),
  1547→        });
  1548→      }
  1549→    }
  1550→
  1551→    // Store achievements in current context
  1552→    if (achievements.length > 0) {
  1553→      this._recentAchievements = [
  1554→        ...achievements,
  1555→        ...(this._recentAchievements || []).slice(0, 20), // Keep last 20
  1556→      ];
  1557→
  1558→      // Broadcast achievements
  1559→      this._broadcastAchievements(achievements);
  1560→    }
  1561→
  1562→    return achievements;
  1563→  }
  1564→
  1565→  /**
  1566→   * Get athlete's career bests from Firebase or cache
  1567→   *
  1568→   * @param {string} athleteName - Athlete name
  1569→   * @returns {Promise<Object|null>} Career bests by event
  1570→   */
  1571→  async _getAthleteCareerBests(athleteName) {
  1572→    if (!athleteName) return null;
  1573→
  1574→    // Check cache first
  1575→    if (!this._careerBestsCache) {
  1576→      this._careerBestsCache = new Map();
  1577→    }
  1578→
  1579→    const cacheKey = athleteName.toLowerCase().trim();
  1580→    if (this._careerBestsCache.has(cacheKey)) {
  1581→      return this._careerBestsCache.get(cacheKey);
  1582→    }
  1583→
  1584→    // Try to load from Firebase
  1585→    const db = getDb();
  1586→    if (db) {
  1587→      try {
  1588→        const athleteKey = this._normalizeNameForKey(athleteName);
  1589→        const snapshot = await db.ref(`athleteStats/${athleteKey}/careerBests`).once('value');
  1590→        const careerBests = snapshot.val();
  1591→
  1592→        if (careerBests) {
  1593→          this._careerBestsCache.set(cacheKey, careerBests);
  1594→          return careerBests;
  1595→        }
  1596→      } catch (error) {
  1597→        console.warn(`[AIContextService] Error loading career bests:`, error);
  1598→      }
  1599→    }
  1600→
  1601→    // Try to get from team data roster (some rosters include season bests)
  1602→    const rosterBests = this._getAthleteFromRoster(athleteName);
  1603→    if (rosterBests?.seasonBests) {
  1604→      this._careerBestsCache.set(cacheKey, rosterBests.seasonBests);
  1605→      return rosterBests.seasonBests;
  1606→    }
  1607→
  1608→    return null;
  1609→  }
  1610→
  1611→  /**
  1612→   * Check if score is a season high
  1613→   *
  1614→   * @param {string} athleteName - Athlete name
  1615→   * @param {string} event - Event code
  1616→   * @param {number} score - Score to check
  1617→   * @returns {Promise<boolean>} True if season high
  1618→   */
  1619→  async _checkSeasonHigh(athleteName, event, score) {
  1620→    // Check session-tracked scores
  1621→    if (!this._sessionScores) {
  1622→      this._sessionScores = new Map();
  1623→    }
  1624→
  1625→    const key = `${athleteName.toLowerCase()}-${event}`;
  1626→    const previousBest = this._sessionScores.get(key) || 0;
  1627→
  1628→    if (score > previousBest) {
  1629→      this._sessionScores.set(key, score);
  1630→      return previousBest > 0; // Only true if there was a previous score
  1631→    }
  1632→
  1633→    return false;
  1634→  }
  1635→
  1636→  /**
  1637→   * Check if score is the athlete's meet high
  1638→   *
  1639→   * @param {string} athleteName - Athlete name
  1640→   * @param {string} event - Event code
  1641→   * @param {number} score - Score to check
  1642→   * @returns {boolean} True if meet high
  1643→   */
  1644→  _checkMeetHigh(athleteName, event, score) {
  1645→    if (!this._virtiusData?.eventResults) return false;
  1646→
  1647→    const eventData = this._virtiusData.eventResults[event];
  1648→    if (!eventData?.gymnasts) return false;
  1649→
  1650→    // Find all scores by this athlete on this event
  1651→    const athleteScores = eventData.gymnasts.filter(
  1652→      g => g.name?.toLowerCase().includes(athleteName.toLowerCase()) ||
  1653→           athleteName.toLowerCase().includes(g.lastName?.toLowerCase() || '')
  1654→    );
  1655→
  1656→    // If only one score, it's their meet high by default
  1657→    if (athleteScores.length <= 1) return false;
  1658→
  1659→    // Check if current score is highest
  1660→    const maxPreviousScore = Math.max(...athleteScores.map(s => s.score || 0));
  1661→    return score >= maxPreviousScore;
  1662→  }
