    83→  async function fetchFromVirtius() {
    84→    if (!virtiusSessionId.trim()) return;
    85→    setVirtiusFetching(true);
    86→    setVirtiusError(null);
    87→
    88→    try {
    89→      const response = await fetch(`https://api.virti.us/session/${virtiusSessionId.trim()}/json`);
    90→      if (!response.ok) throw new Error('Session not found');
    91→      const data = await response.json();
    92→
    93→      const meet = data.meet;
    94→      const teams = meet.teams || [];
    95→
    96→      // Sort teams by team_order if available
    97→      const sortedTeams = [...teams].sort((a, b) => (a.team_order || 0) - (b.team_order || 0));
    98→
    99→      // Infer competition type and extract gender for proper team lookups
   100→      const compType = inferCompType(meet.sex, sortedTeams.length);
   101→      const gender = meet.sex === 'women' ? 'womens' : 'mens';
   102→
   103→      setFormData(prev => ({
   104→        ...prev,
   105→        eventName: meet.name || prev.eventName,
   106→        meetDate: formatDate(meet.meet_date) || prev.meetDate,
   107→        venue: meet.location?.split(',')[0]?.trim() || prev.venue,
   108→        location: meet.location?.split(',').slice(1).join(',').trim() || prev.location,
   109→        compType,
   110→        gender, // Set explicit gender from Virtius data
   111→        team1Name: sortedTeams[0]?.name || prev.team1Name,
   112→        team1Logo: getTeamLogo(sortedTeams[0]?.name, gender) || prev.team1Logo,
   113→        team1Tricode: sortedTeams[0]?.tricode || prev.team1Tricode,
   114→        team2Name: sortedTeams[1]?.name || prev.team2Name,
   115→        team2Logo: getTeamLogo(sortedTeams[1]?.name, gender) || prev.team2Logo,
   116→        team2Tricode: sortedTeams[1]?.tricode || prev.team2Tricode,
   117→        team3Name: sortedTeams[2]?.name || prev.team3Name,
   118→        team3Logo: getTeamLogo(sortedTeams[2]?.name, gender) || prev.team3Logo,
   119→        team3Tricode: sortedTeams[2]?.tricode || prev.team3Tricode,
   120→        team4Name: sortedTeams[3]?.name || prev.team4Name,
   121→        team4Logo: getTeamLogo(sortedTeams[3]?.name, gender) || prev.team4Logo,
   122→        team4Tricode: sortedTeams[3]?.tricode || prev.team4Tricode,
   123→        team5Name: sortedTeams[4]?.name || prev.team5Name,
   124→        team5Logo: getTeamLogo(sortedTeams[4]?.name, gender) || prev.team5Logo,
   125→        team5Tricode: sortedTeams[4]?.tricode || prev.team5Tricode,
   126→        team6Name: sortedTeams[5]?.name || prev.team6Name,
   127→        team6Logo: getTeamLogo(sortedTeams[5]?.name, gender) || prev.team6Logo,
   128→        team6Tricode: sortedTeams[5]?.tricode || prev.team6Tricode,
   129→        virtiusSessionId: virtiusSessionId.trim(),
   130→      }));
   131→    } catch (error) {
   132→      setVirtiusError('Could not fetch Virtius session. Check the session ID and try again.');
   133→    } finally {
   134→      setVirtiusFetching(false);
   135→    }
   136→  }
