    50→    };
    51→  }
    52→
    53→
    54→  // Generate a random competition ID
    55→  function generateCompId() {
    56→    const chars = 'abcdefghijklmnopqrstuvwxyz0123456789';
    57→    let result = '';
    58→    for (let i = 0; i < 8; i++) {
    59→      result += chars.charAt(Math.floor(Math.random() * chars.length));
    60→    }
    61→    return result;
    62→  }
    63→
    64→  // Format date from YYYY-MM-DD to readable format
    65→  function formatDate(dateStr) {
    66→    if (!dateStr) return '';
    67→    const date = new Date(dateStr + 'T00:00:00');
    68→    return date.toLocaleDateString('en-US', {
    69→      year: 'numeric', month: 'long', day: 'numeric'
    70→    });
    71→  }
