    73→  // Infer competition type from sex and team count
    74→  function inferCompType(sex, teamCount) {
    75→    const prefix = sex === 'women' ? 'womens' : 'mens';
    76→    const suffix = teamCount === 2 ? 'dual' :
    77→                   teamCount === 3 ? 'tri' :
    78→                   teamCount === 4 ? 'quad' :
    79→                   teamCount === 5 ? '5-team' : '6-team';
