     1→/**
     2→ * AI Context Service
     3→ *
     4→ * Provides real-time AI-generated context and talking points during live show
     5→ * execution. This service is used during show runtime (as opposed to
     6→ * aiSuggestionService which is used during planning).
     7→ *
     8→ * Phase C: AI Context - Live Execution (P3)
     9→ * Task 55: Create AIContextService stub
    10→ * Task 56: Add `aiContextUpdated` socket event
    11→ * Task 57: Create `useAIContext` hook
    12→ * Task 58: Integrate with Virtius API for live stats
    13→ * Task 59: Generate talking points in real-time
    14→ * Task 60: Detect career highs, records during show
    15→ * Task 61: Display AI context in Talent View
    16→ * Task 62: Display AI context in Producer View
    17→ */
    18→
    19→import { getDb } from './productionConfigService.js';
    20→
    21→// ============================================================================
    22→// Virtius API Configuration
    23→// ============================================================================
    24→
    25→const VIRTIUS_API_BASE = 'https://api.virti.us';
    26→
    27→/**
    28→ * Event code mappings between different systems
    29→ */
    30→const EVENT_MAPPINGS = {
    31→  // Virtius event names to short codes
    32→  virtiusToShort: {
    33→    FLOOR: 'FX',
    34→    HORSE: 'PH',
    35→    RINGS: 'SR',
    36→    VAULT: 'VT',
    37→    PBARS: 'PB',
    38→    BAR: 'HB',
    39→    BARS: 'UB',
    40→    BEAM: 'BB',
    41→  },
    42→  // Short codes to display names
    43→  shortToDisplay: {
    44→    FX: 'Floor Exercise',
    45→    PH: 'Pommel Horse',
    46→    SR: 'Still Rings',
    47→    VT: 'Vault',
    48→    PB: 'Parallel Bars',
    49→    HB: 'High Bar',
    50→    UB: 'Uneven Bars',
    51→    BB: 'Balance Beam',
    52→  },
    53→};
    54→
    55→// ============================================================================
    56→// Constants
    57→// ============================================================================
    58→
    59→/**
    60→ * Context types that can be generated
    61→ */
    62→const CONTEXT_TYPES = {
    63→  SEGMENT: 'segment',           // Context for current segment
    64→  ATHLETE: 'athlete',           // Athlete-specific talking points
    65→  SCORE: 'score',              // Score-related context (career high, etc.)
    66→  MATCHUP: 'matchup',          // Head-to-head matchup context
    67→  MILESTONE: 'milestone',       // Milestone alerts (100th routine, etc.)
    68→  BREAKING: 'breaking',         // Breaking news / live updates
    69→};
    70→
    71→/**
    72→ * Priority levels for context items
    73→ */
    74→const PRIORITY = {
    75→  CRITICAL: 'critical',   // Must mention (career high, record, etc.)
    76→  HIGH: 'high',          // Should mention if time allows
    77→  MEDIUM: 'medium',      // Nice to have
    78→  LOW: 'low',            // Background info only
    79→};
    80→
    81→/**
    82→ * Default configuration
    83→ */
    84→const DEFAULT_CONFIG = {
    85→  updateIntervalMs: 5000,      // How often to check for new context
    86→  maxTalkingPoints: 5,         // Max talking points per segment
    87→  lookAheadSegments: 2,        // Number of upcoming segments to prep
    88→};
    89→
    90→/**
    91→ * Segment type patterns for context generation
    92→ */
    93→const SEGMENT_PATTERNS = {
    94→  rotation: /rotation\s*(\d+)/i,
    95→  event: /\b(floor|vault|bars|beam|rings|pommel|parallel|high bar|fx|vt|ub|bb|sr|ph|pb|hb)\b/i,
    96→  team: /\b(intro|introduction|welcome)\b/i,
    97→  interview: /\b(interview|feature|spotlight|profile)\b/i,
    98→  scoring: /\b(score|scoring|results?|standings?)\b/i,
    99→  break: /\b(break|intermission|halftime)\b/i,
   100→  opening: /\b(open|opening|pre-?show|warmup)\b/i,
   101→  closing: /\b(close|closing|post-?show|wrap|finale)\b/i,
   102→};
   103→
   104→/**
   105→ * Event short code to full name mapping
   106→ */
   107→const EVENT_FULL_NAMES = {
   108→  FX: 'Floor Exercise',
   109→  VT: 'Vault',
   110→  UB: 'Uneven Bars',
   111→  BB: 'Balance Beam',
   112→  PH: 'Pommel Horse',
   113→  SR: 'Still Rings',
   114→  PB: 'Parallel Bars',
   115→  HB: 'High Bar',
   116→};
   117→
   118→// ============================================================================
   119→// AI Context Service Class
   120→// ============================================================================
   121→
   122→/**
   123→ * AIContextService manages real-time context generation for live shows.
   124→ *
   125→ * It subscribes to show state changes and generates relevant talking points
   126→ * for talent based on:
   127→ * - Current segment type and content
   128→ * - Live scores from Virtius API
   129→ * - Athlete statistics and milestones
   130→ * - Historical matchup data
   131→ */
   132→class AIContextService {
   133→  /**
   134→   * Create an AIContextService instance
   135→   *
   136→   * @param {Object} options - Configuration options
   137→   * @param {string} options.compId - Competition ID
   138→   * @param {Object} options.io - Socket.io instance for broadcasting
   139→   * @param {Object} options.engine - TimesheetEngine instance (optional)
   140→   */
   141→  constructor(options = {}) {
   142→    this.compId = options.compId || null;
   143→    this.io = options.io || null;
   144→    this.engine = options.engine || null;
   145→    this.config = { ...DEFAULT_CONFIG, ...options.config };
   146→
   147→    // State
   148→    this._isRunning = false;
   149→    this._currentContext = null;
   150→    this._updateInterval = null;
   151→    this._lastSegmentId = null;
   152→
   153→    // Cached data
   154→    this._competitionConfig = null;
   155→    this._teamData = null;
   156→    this._athleteStats = null;
   157→
   158→    // Virtius API state
   159→    this._virtiusSessionId = null;
   160→    this._virtiusData = null;
   161→    this._virtiusLastFetch = null;
   162→    this._virtiusCacheMs = 10000; // Refresh Virtius data every 10 seconds
   163→  }
   164→
   165→  // ==========================================================================
   166→  // Lifecycle Methods
   167→  // ==========================================================================
   168→
   169→  /**
   170→   * Start the AI context service
   171→   *
   172→   * Begins monitoring the show and generating context updates.
   173→   */
   174→  async start() {
   175→    if (this._isRunning) {
   176→      console.log(`[AIContextService] Already running for ${this.compId}`);
   177→      return;
   178→    }
   179→
   180→    console.log(`[AIContextService] Starting for competition ${this.compId}`);
   181→    this._isRunning = true;
   182→
   183→    // Load initial competition data
   184→    await this._loadCompetitionData();
   185→
   186→    // Start periodic context updates
   187→    this._updateInterval = setInterval(
   188→      () => this._updateContext(),
   189→      this.config.updateIntervalMs
   190→    );
   191→
   192→    // Generate initial context
   193→    await this._updateContext();
   194→  }
   195→
   196→  /**
   197→   * Stop the AI context service
   198→   */
   199→  stop() {
   200→    if (!this._isRunning) {
   201→      return;
   202→    }
   203→
   204→    console.log(`[AIContextService] Stopping for competition ${this.compId}`);
   205→    this._isRunning = false;
   206→
   207→    if (this._updateInterval) {
   208→      clearInterval(this._updateInterval);
   209→      this._updateInterval = null;
   210→    }
   211→
   212→    this._currentContext = null;
   213→    this._lastSegmentId = null;
   214→  }
   215→
   216→  /**
   217→   * Check if service is running
   218→   */
   219→  get isRunning() {
   220→    return this._isRunning;
   221→  }
   222→
   223→  // ==========================================================================
   224→  // Context Generation (Stubs - to be implemented in Task 59)
   225→  // ==========================================================================
   226→
   227→  /**
   228→   * Update context based on current show state
   229→   *
   230→   * This is the main context generation loop. It:
   231→   * 1. Checks current segment
   232→   * 2. Queries for relevant context
   233→   * 3. Generates talking points
   234→   * 4. Broadcasts updates
   235→   */
   236→  async _updateContext() {
   237→    if (!this._isRunning) return;
   238→
   239→    try {
   240→      // Get current show state
   241→      const showState = this._getShowState();
   242→      if (!showState || showState.showState !== 'RUNNING') {
   243→        return;
   244→      }
   245→
   246→      const currentSegment = showState.currentSegment;
   247→      if (!currentSegment) return;
   248→
   249→      // Only regenerate if segment changed
   250→      if (currentSegment.id === this._lastSegmentId) {
   251→        return;
   252→      }
   253→
   254→      this._lastSegmentId = currentSegment.id;
   255→
   256→      // Generate context for this segment (stub - returns placeholder data)
   257→      const context = await this._generateSegmentContext(currentSegment);
   258→
   259→      // Store and broadcast
   260→      this._currentContext = context;
   261→      this._broadcastContext(context);
   262→    } catch (error) {
   263→      console.error(`[AIContextService] Error updating context:`, error);
   264→    }
   265→  }
   266→
   267→  /**
   268→   * Generate context for a specific segment
   269→   *
   270→   * @param {Object} segment - Current segment data
   271→   * @returns {Promise<Object>} Generated context
   272→   */
   273→  async _generateSegmentContext(segment) {
   274→    const context = {
   275→      segmentId: segment.id,
   276→      segmentName: segment.name,
   277→      timestamp: new Date().toISOString(),
   278→      talkingPoints: [],
   279→      athleteContext: [],
   280→      scoreContext: null,
   281→      milestones: [],
   282→      achievements: [],
   283→      liveScores: null,
   284→    };
   285→
   286→    // Fetch live scores from Virtius
   287→    const liveScores = await this.fetchLiveScores();
   288→    if (liveScores.available) {
   289→      context.liveScores = {
   290→        teams: liveScores.teams,
   291→        currentRotation: liveScores.currentRotation,
   292→        recentScores: liveScores.recentScores,
   293→      };
   294→
   295→      // Add score-based talking points
   296→      const scorePoints = this._getScoreBasedTalkingPoints(liveScores, segment);
   297→      context.talkingPoints.push(...scorePoints);
   298→
   299→      // Scan for career highs and records (Task 60)
   300→      const achievements = await this.scanForAchievements();
   301→      context.achievements = achievements;
   302→
   303→      // Add achievement-based talking points
   304→      const achievementPoints = this._getAchievementTalkingPoints(achievements);
   305→      context.talkingPoints.push(...achievementPoints);
   306→    }
   307→
   308→    // Generate basic talking points based on segment type
   309→    const basicPoints = this._getBasicTalkingPoints(segment);
   310→    context.talkingPoints.push(...basicPoints);
   311→
   312→    // Sort talking points by priority
   313→    context.talkingPoints.sort((a, b) => {
   314→      const priorityOrder = { critical: 0, high: 1, medium: 2, low: 3 };
   315→      return (priorityOrder[a.priority] || 3) - (priorityOrder[b.priority] || 3);
   316→    });
   317→
   318→    // Limit to max configured talking points
   319→    context.talkingPoints = context.talkingPoints.slice(0, this.config.maxTalkingPoints);
   320→
   321→    return context;
   322→  }
   323→
   324→  /**
   325→   * Generate talking points from detected achievements
   326→   *
   327→   * @param {Array} achievements - Detected achievements
   328→   * @returns {Array} Achievement-based talking points
   329→   */
   330→  _getAchievementTalkingPoints(achievements) {
   331→    const points = [];
   332→
   333→    for (const achievement of achievements) {
   334→      const eventName = EVENT_FULL_NAMES[achievement.event] || achievement.event;
   335→
   336→      if (achievement.type === 'career_high') {
   337→        points.push({
   338→          id: `career-high-${achievement.athleteName}-${Date.now()}`,
   339→          type: CONTEXT_TYPES.SCORE,
   340→          priority: PRIORITY.CRITICAL,
   341→          text: `🎉 CAREER HIGH! ${achievement.athleteName} just scored ${achievement.score.toFixed(3)} on ${eventName} - beats previous best of ${achievement.previousHigh?.toFixed(3)} by ${achievement.improvement}!`,
   342→          source: 'achievement-detection',
   343→          data: achievement,
   344→        });
   345→      } else if (achievement.type === 'season_high') {
   346→        points.push({
   347→          id: `season-high-${achievement.athleteName}-${Date.now()}`,
   348→          type: CONTEXT_TYPES.SCORE,
   349→          priority: PRIORITY.HIGH,
   350→          text: `⭐ SEASON HIGH! ${achievement.athleteName} scores ${achievement.score.toFixed(3)} on ${eventName} - their best of the season!`,
   351→          source: 'achievement-detection',
   352→          data: achievement,
   353→        });
   354→      } else if (achievement.type === 'record_broken') {
   355→        const record = achievement.records[0];
   356→        const recordType = record.type === 'school' ? 'SCHOOL RECORD' : 'MEET RECORD';
   357→        points.push({
   358→          id: `record-${achievement.athleteName}-${Date.now()}`,
   359→          type: CONTEXT_TYPES.MILESTONE,
   360→          priority: PRIORITY.CRITICAL,
   361→          text: `🏆 NEW ${recordType}! ${achievement.athleteName} breaks the ${eventName} record with ${achievement.score.toFixed(3)}! Previous record: ${record.previousScore.toFixed(3)} by ${record.previousHolder}`,
   362→          source: 'achievement-detection',
   363→          data: achievement,
   364→        });
   365→      } else if (achievement.type === 'record_tied') {
   366→        const record = achievement.tiedRecords[0];
   367→        const recordType = record.type === 'school' ? 'school record' : 'meet record';
   368→        points.push({
   369→          id: `record-tied-${achievement.athleteName}-${Date.now()}`,
   370→          type: CONTEXT_TYPES.MILESTONE,
   371→          priority: PRIORITY.HIGH,
   372→          text: `📊 ${achievement.athleteName} TIES the ${recordType} on ${eventName} with ${achievement.score.toFixed(3)}!`,
   373→          source: 'achievement-detection',
   374→          data: achievement,
   375→        });
   376→      }
   377→    }
   378→
   379→    return points;
   380→  }
   381→
   382→  /**
   383→   * Generate talking points based on live score data
   384→   *
   385→   * @param {Object} liveScores - Live scores from Virtius
   386→   * @param {Object} segment - Current segment
   387→   * @returns {Array} Score-based talking points
   388→   */
   389→  _getScoreBasedTalkingPoints(liveScores, segment) {
   390→    const points = [];
   391→
   392→    // Add team standings talking point
   393→    if (liveScores.teams?.length >= 2) {
   394→      const [leader, second] = liveScores.teams;
   395→      const margin = ((leader.score || 0) - (second.score || 0)).toFixed(3);
   396→
   397→      if (margin > 0) {
   398→        points.push({
   399→          id: `standings-${Date.now()}`,
   400→          type: CONTEXT_TYPES.SCORE,
   401→          priority: margin > 1 ? PRIORITY.MEDIUM : PRIORITY.HIGH,
   402→          text: `${leader.name} leads ${second.name} by ${margin} points`,
   403→          source: 'live-scores',
   404→          data: { leader, second, margin: parseFloat(margin) },
   405→        });
   406→      } else if (margin === '0.000') {
   407→        points.push({
   408→          id: `standings-tied-${Date.now()}`,
   409→          type: CONTEXT_TYPES.SCORE,
   410→          priority: PRIORITY.HIGH,
   411→          text: `${leader.name} and ${second.name} are TIED at ${leader.score?.toFixed(3)}`,
   412→          source: 'live-scores',
   413→          data: { leader, second, tied: true },
   414→        });
   415→      }
   416→    }
   417→
   418→    // Highlight recent high scores
   419→    if (liveScores.recentScores?.length > 0) {
   420→      const topScore = liveScores.recentScores[0];
   421→      if (topScore.score >= 9.9) {
   422→        points.push({
   423→          id: `high-score-${Date.now()}`,
   424→          type: CONTEXT_TYPES.SCORE,
   425→          priority: topScore.score >= 10.0 ? PRIORITY.CRITICAL : PRIORITY.HIGH,
   426→          text: `${topScore.athlete} (${topScore.team}) just scored ${topScore.score.toFixed(3)} on ${topScore.eventDisplay}!`,
   427→          source: 'live-scores',
   428→          data: topScore,
   429→        });
   430→      }
   431→    }
   432→
   433→    // Add rotation context
   434→    if (liveScores.currentRotation) {
   435→      points.push({
   436→        id: `rotation-${Date.now()}`,
   437→        type: CONTEXT_TYPES.SEGMENT,
   438→        priority: PRIORITY.LOW,
   439→        text: `Currently in rotation ${liveScores.currentRotation}`,
   440→        source: 'live-scores',
   441→        data: { rotation: liveScores.currentRotation },
   442→      });
   443→    }
   444→
   445→    return points;
   446→  }
   447→
   448→  /**
   449→   * Get basic talking points for a segment type
   450→   *
   451→   * Enhanced in Task 59 with intelligent context-aware generation based on:
   452→   * - Segment name/type patterns
   453→   * - Team data (seniors, rankings, coaches)
   454→   * - Event-specific context
   455→   * - Matchup analysis
   456→   *
   457→   * @param {Object} segment - Segment data
   458→   * @returns {Array} Talking points
   459→   */
   460→  _getBasicTalkingPoints(segment) {
   461→    const points = [];
   462→
   463→    // Always include segment notes if present (highest priority)
   464→    if (segment.notes) {
   465→      points.push({
   466→        id: `notes-${segment.id}`,
   467→        type: CONTEXT_TYPES.SEGMENT,
   468→        priority: PRIORITY.HIGH,
   469→        text: segment.notes,
   470→        source: 'segment-notes',
   471→      });
   472→    }
   473→
   474→    // Analyze segment name for context patterns
   475→    const segmentName = segment.name || '';
   476→    const segmentContext = this._analyzeSegmentName(segmentName);
   477→
   478→    // Generate points based on segment context
   479→    if (segmentContext.isRotation) {
   480→      points.push(...this._getRotationTalkingPoints(segmentContext, segment));
   481→    }
   482→
   483→    if (segmentContext.isTeamIntro) {
   484→      points.push(...this._getTeamIntroTalkingPoints(segment));
   485→    }
   486→
   487→    if (segmentContext.isInterview) {
   488→      points.push(...this._getInterviewTalkingPoints(segment));
   489→    }
   490→
   491→    if (segmentContext.isScoring) {
   492→      points.push(...this._getScoringTalkingPoints(segment));
   493→    }
   494→
   495→    if (segmentContext.isOpening) {
   496→      points.push(...this._getOpeningTalkingPoints(segment));
   497→    }
   498→
   499→    if (segmentContext.isClosing) {
   500→      points.push(...this._getClosingTalkingPoints(segment));
   501→    }
   502→
   503→    if (segmentContext.isBreak) {
   504→      points.push(...this._getBreakTalkingPoints(segment));
   505→    }
   506→
   507→    // Add event-specific talking points if an event is detected
   508→    if (segmentContext.event) {
   509→      points.push(...this._getEventTalkingPoints(segmentContext.event, segment));
   510→    }
   511→
   512→    // Add matchup context if we have team data
   513→    if (this._teamData) {
   514→      const matchupPoints = this._getMatchupTalkingPoints(segment);
   515→      points.push(...matchupPoints);
   516→    }
   517→
   518→    // Add type-specific context
   519→    if (segment.type === 'live' || segment.type === 'LIVE') {
   520→      points.push({
   521→        id: `live-${segment.id}`,
   522→        type: CONTEXT_TYPES.SEGMENT,
   523→        priority: PRIORITY.LOW,
   524→        text: 'Live segment - engage with the audience',
   525→        source: 'segment-type',
   526→      });
   527→    }
   528→
   529→    return points;
   530→  }
   531→
   532→  /**
   533→   * Analyze segment name to extract context patterns
   534→   *
   535→   * @param {string} name - Segment name
   536→   * @returns {Object} Extracted context
   537→   */
   538→  _analyzeSegmentName(name) {
   539→    const context = {
   540→      isRotation: false,
   541→      rotationNumber: null,
   542→      event: null,
   543→      isTeamIntro: false,
