   974→function countByClassYear(teamDataMap, teams) {
   975→  const counts = {
   976→    freshmen: 0,  // year 1
   977→    sophomores: 0, // year 2
   978→    juniors: 0,   // year 3
   979→    seniors: 0,   // year 4
   980→    byTeam: {},
   981→  };
   982→
   983→  teams.forEach(team => {
   984→    const teamData = teamDataMap?.[`team${team.slot}`];
   985→    const roster = teamData?.roster || [];
   986→    const teamCounts = { freshmen: 0, sophomores: 0, juniors: 0, seniors: 0 };
   987→
   988→    roster.forEach(athlete => {
   989→      switch (athlete.year) {
   990→        case 1: counts.freshmen++; teamCounts.freshmen++; break;
   991→        case 2: counts.sophomores++; teamCounts.sophomores++; break;
   992→        case 3: counts.juniors++; teamCounts.juniors++; break;
   993→        case 4: counts.seniors++; teamCounts.seniors++; break;
   994→      }
   995→    });
   996→
   997→    counts.byTeam[team.name] = teamCounts;
   998→  });
   999→
  1000→  return counts;
  1001→}
