  1003→/**
  1004→ * Query All-Americans from athlete honors data
  1005→ *
  1006→ * All-American status is stored in teamsDatabase/honors/{athlete-name-lowercase}
  1007→ * Structure: { name, team, honors: [{ year, type, event }] }
  1008→ *
  1009→ * Example honors types:
  1010→ * - "First Team All-American"
  1011→ * - "Second Team All-American"
  1012→ * - "All-American"
  1013→ * - "All-Conference"
  1014→ *
  1015→ * @param {Object} db - Firebase database reference
  1016→ * @param {Array} teams - Teams in the competition
  1017→ * @returns {Promise<Array>} All-Americans competing in this meet
  1018→ */
  1019→async function queryAllAmericans(db, teams) {
  1020→  const allAmericans = [];
  1021→
  1022→  if (!db) return allAmericans;
  1023→
  1024→  try {
  1025→    // Check if honors database exists
  1026→    const honorsSnapshot = await db.ref('teamsDatabase/honors').once('value');
  1027→    const honorsData = honorsSnapshot.val();
  1028→
  1029→    if (!honorsData) {
  1030→      // Honors database not yet populated - this is expected for now
  1031→      // Future: integrate with Virtius API or manual data entry
  1032→      return allAmericans;
  1033→    }
  1034→
  1035→    // Build a set of athlete names from competing teams for quick lookup
  1036→    const competingAthletes = new Map();
  1037→    teams.forEach(team => {
  1038→      const roster = team.roster || [];
  1039→      roster.forEach(athlete => {
  1040→        const key = athlete.fullName?.toLowerCase() ||
  1041→          `${athlete.firstName} ${athlete.lastName}`.toLowerCase();
  1042→        competingAthletes.set(key, { ...athlete, team: team.name, teamSlot: team.slot });
  1043→      });
  1044→    });
  1045→
  1046→    // Find All-Americans among competing athletes
  1047→    Object.entries(honorsData).forEach(([key, honorData]) => {
  1048→      if (competingAthletes.has(key)) {
  1049→        const athlete = competingAthletes.get(key);
  1050→        const allAmericanHonors = (honorData.honors || []).filter(h =>
  1051→          h.type?.toLowerCase().includes('all-american')
  1052→        );
  1053→
  1054→        if (allAmericanHonors.length > 0) {
  1055→          allAmericans.push({
  1056→            name: athlete.fullName || `${athlete.firstName} ${athlete.lastName}`,
  1057→            firstName: athlete.firstName,
  1058→            lastName: athlete.lastName,
  1059→            team: athlete.team,
  1060→            teamSlot: athlete.teamSlot,
  1061→            honors: allAmericanHonors,
  1062→            honorCount: allAmericanHonors.length,
  1063→            // Most recent All-American honor
  1064→            mostRecent: allAmericanHonors.sort((a, b) =>
  1065→              (b.year || 0) - (a.year || 0)
  1066→            )[0],
  1067→          });
  1068→        }
  1069→      }
  1070→    });
  1071→
  1072→    // Sort by honor count (most decorated first)
  1073→    return allAmericans.sort((a, b) => b.honorCount - a.honorCount);
  1074→  } catch (error) {
  1075→    console.warn('[AISuggestionService] Error querying All-Americans:', error.message);
  1076→    return allAmericans;
  1077→  }
  1078→}
