      const statsNotes = teamStats.seasonHigh
        ? `${team.name} season avg: ${teamStats.seasonAverage.toFixed(3)}, high: ${teamStats.seasonHigh.toFixed(3)}`
        : `${team.name} season avg: ${teamStats.seasonAverage.toFixed(3)}`;

      segments.push({
