        confidence: matchupConf.confidence,
        confidenceLevel: matchupConf.confidenceLevel,
        category: 'special',
        reason: buildReasonString('Close matchup - rivalry context adds value', matchupConf.reasons),
      });
    }
  }

  return segments;
}

